/* 由 tools/build_lib.js 从 tools/lib_notes/honglou/*.json 组装，请勿手改。 */
LIT.addLibNotes({"honglou_zanghua":{"intro":"第二十七回饯花之日，黛玉因前一夜被晴雯拒之门外、错怪了宝玉，独自到花冢葬花，哭吟这首《葬花吟》；第二十八回开头写宝玉在山坡上听见，恸倒在地。诗是黛玉的自悼，常被读者看作她命运的谶语。读这两段，要看诗句怎样从惜花转到自伤，以及宝玉的“反复推求”怎样把一个人的哀伤推到园中所有人身上。","focus":["《葬花吟》用歌行体，句子长短参差、反复咏叹。前半写花：花谢花飞、红消香断；“一年三百六十日，风刀霜剑严相逼”把花的遭遇转成人的处境；结尾“侬今葬花人笑痴，他年葬侬知是谁”，由葬花人变成想象中的被葬者，惜花彻底转为自悼。","诗里同时有两种自我形象：一是寄人篱下、受“风刀霜剑”相逼的孤女，一是“质本洁来还洁去”的高洁自许。前者是处境，后者是态度，黛玉的悲剧正在于她不肯为处境改变态度。","第二十八回开头宝玉的感悟是“一而二，二而三，反复推求”：由黛玉终归无可寻觅，推到宝钗、香菱、袭人，再推到自己、园子、花柳。作者借宝玉把个人的哀伤扩展成对一切美好终将散尽的体认，这正是全书“盛筵必散”的底色。"],"notes":[["饯花之期","饯别花神的节日，旧俗在芒种这天"],["红消香断","花色褪尽、香气断绝"],["风刀霜剑","像刀剑一样的风霜，喻环境的冷酷逼迫"],["侬","我，吴语自称"],["痴","痴傻、执迷"],["恸倒","极度悲痛而倒下"],["宁不","岂不，难道不"],["推求","推想、探究"],["大造","天地造化"],["尘网","尘世的罗网"]],"think":["宝玉听完《葬花吟》后“反复推求”，从黛玉推到宝钗、香菱、袭人，再推到自己和整个园子。你觉得这是他对黛玉一个人的心疼，还是另一种更大的悲哀？","两层都有：恸倒是为黛玉，但他接着把“无可寻觅”推及众人和万物，说明他悲的是美好事物整体的必然消逝。判断时可以对照第五回的判词和全书走向：作者让宝玉在这里第一次清楚地意识到“散”，这和单纯的儿女情长不同。"],"quiz":[["“一年三百六十日，风刀霜剑严相逼”在诗中的作用是？",["由写花转到写人的处境","交代葬花的具体日期","描写园中的天气"],"表面仍写花受风霜摧折，实际写黛玉寄人篱下的处境，是由花到人的转折。"],["“侬今葬花人笑痴，他年葬侬知是谁”体现了什么转变？",["从葬花人变成想象中的被葬者","从悲伤转为欢喜","从写景转为写人物外貌"],"前句自己是葬花人，后句设想自己死后无人埋葬，惜花变成了自悼。"],["宝玉听后“反复推求”，推到了哪些人？",["宝钗、香菱、袭人，以至自己","贾母、王夫人、凤姐","晴雯、紫鹃、雪雁"],"原文：“推之于他人，如宝钗，香菱，袭人等”，再推到“自身尚不知何在何往”。"]],"cards":[["侬今葬花人笑痴，下句是？","他年葬侬知是谁？"],["宝玉恸倒后的“反复推求”说明什么？","他从黛玉推及众人、自身和园子，体认到一切美好终将散尽。"]],"line":["一朝春尽红颜老，花落人亡两不知","整理老家旧照片，翻到外婆年轻时的样子，忽然懂了那句：一朝春尽红颜老，花落人亡两不知。"],"tags":["林黛玉","葬花吟","贾宝玉"]},"honglou_shitou":{"intro":"第一回先讲两则神话。一是女娲补天剩下的一块顽石，自叹无材，求僧道携入红尘；二是甄士隐梦中听见的绛珠草还泪公案。两则合起来，交代了全书的两个出发点：一个“无材补天”的失意者，一段以眼泪偿还的情债。读时抓住石头的自我认知和“美中不足，好事多魔”那句预警。","focus":["石头的口气很有分寸：“独自己无材不堪入选”，是先被淘汰、后才动凡心。它向僧道求的是“富贵场中，温柔乡里受享几年”，求的不是功名，是享受，这为宝玉后来厌弃仕途、贪恋闺阁的性情埋下根子。","僧道的答话是全书最早的总评：“乐极悲生，人非物换，究竟是到头一梦，万境归空”。作者让故事的结局在开头就被说破，读者之后看的不是“会怎样”，而是“怎样一步步如此”。","梦中公案把“情”写成一笔债：神瑛侍者灌溉，绛珠草“但把我一生所有的眼泪还他”。债的算法很具体，不是抽象的缘分，所以黛玉一生多泪在叙事上有了因果，也呼应后文“欠泪的，泪已尽”。"],"notes":[["无材","没有可用之才，指未被选去补天"],["灵性已通","经煅炼后有了知觉"],["凡心","对世俗荣华的向往"],["红尘","人间世俗"],["美中不足","好中有缺"],["乐极悲生","快乐到顶便转为悲伤"],["万境归空","一切境遇终归虚无"],["温柔富贵乡","安逸富贵的去处"],["三生石畔","灵河岸边的石头旁，喻前缘"],["绛珠草","黛玉的前身"],["神瑛侍者","宝玉的前身"],["风流冤家","情缘纠缠的一干人"],["离恨天","虚构的天界名"],["蠢物","僧道对石头的称呼"]],"think":["石头是自己“求”下凡的，不是被罚下凡。这个设定对理解宝玉有什么作用？","作用在于他的入世带有主动的、天真的欲望，而不是被动受难。后来的悲剧因而带有“当初所求即所失”的反讽：求温柔富贵，得到的恰是繁华的消散。判断时可对照僧道“切莫后悔”的叮嘱。"],"quiz":[["石头恳求僧道携它入红尘，最直接的动机是？",["听说人间荣华富贵，心生向往","想去人间补天济世","被女娲罚下凡间受苦"],"原文写它听见僧道谈“荣华富贵”后“不觉打动凡心”，所求是受享，而不是补天或受罚。"],["绛珠仙子决定下世为人，打算怎样报答神瑛侍者的灌溉之恩？",["把一生的眼泪还给他","以灵草之身供他入药","助他修成仙体"],"原文：“但把我一生所有的眼泪还他，也偿还得过他了”，这是“还泪”之说的出处。"]],"cards":[["“美中不足，好事多魔”出自谁之口？","僧道向石头说明红尘不可久恃时所说。"],["绛珠草为何要下凡？","神瑛侍者曾日日以甘露灌溉，她要以一生眼泪偿还此恩。"]],"line":["但把我一生所有的眼泪还他，也偿还得过他了","朋友为一件旧事耿耿多年，我劝他：有的账只能用时间和眼泪还，“但把我一生所有的眼泪还他”，别再算利息了。"],"tags":["神话框架","还泪","顽石"]},"honglou_lengzi":{"intro":"第二回由失意的贾雨村在扬州城外遇见古董商冷子兴，两人闲谈，借“演说”把荣国府的世系、人口和宝玉的来历一口气交代出来。更重要的是雨村那番“正邪两赋”之论：它是作者给宝玉这一类人物预先下的一个总体判断。读时留意两个人对宝玉的评价如何相反。","focus":["子兴叙世系用的是账房口气：宁公居长生四子，荣公一脉两子，哪房出什么人，一句不乱。宁府一句“把宁国府竟翻了过来，也没有人敢来管他”，荣府一句“酷喜捕潦”，两三笔就把两府的气味分开了。","抓周一段是对宝玉最早的“定性”。他“一概不取，伸手只把些脂粉钗环抓来”，政老爹便断定“将来酒色之徒耳”；宝玉自己那句“女儿是水作的骨肉，男人是泥作的骨肉”，在子兴口中是“将来色鬼无疑”。作者让这些评价都出自旁人，宝玉本人还没出场。","雨村的“正邪两赋”把人分为大仁、大恶，以及秉正邪二气相搏而生者。后者“聪俊灵秀之气，则在万万人之上，其乖僻邪谬不近人情之态，又在万万人之下”，生于公侯富贵之家则成“情痴情种”。这是用类型论替宝玉辩护，但举例连陶潜、阮籍与陈后主、宋徽宗并列，立场并不单纯。"],"notes":[["一母同胞","同一个母亲所生"],["袭官","承袭先人官职"],["捕潦","原文如此，疑为传抄之误，此处形容政老爹喜读书"],["周岁","满一岁，当时有摆物抓取测志向的习俗"],["脂粉钗环","女子用品"],["酒色之徒","沉溺酒色的人"],["罕然厉色","吃惊而神色严厉"],["应运而生","顺着时运出生"],["应劫而生","应劫数出生"],["清明灵秀","清朗聪明"],["乖僻邪谬","古怪偏执、不合常理"],["情痴情种","痴于情的人"],["逸士高人","隐逸的高人"],["奇优名倡","出色的艺人"],["易地则同","换了处境便相同"]],"think":["雨村把陶潜、阮籍和陈后主、宋徽宗放进同一份名单，你觉得这是在夸宝玉，还是在为他预留一个不好的结局？","两者都有。名单里既有不合流俗的高士，也有亡国之君与失意之人，说明“情痴”这类人才华与祸患同源。可对照第五回判词与全书结局，这个“既奇又险”的定位贯穿始终。"],"quiz":[["雨村认为宝玉这类人若生在公侯富贵之家，会成为什么？",["情痴情种","逸士高人","奇优名倡"],"原文按出身分三类：“生于公侯富贵之家，则为情痴情种；生于诗书清贫之族，则为逸士高人；生于薄祚寒门，则为奇优名倡”。"],["子兴转述政老爹看到宝玉抓周的反应，说明政老爹怎样看他？",["认为他将来是酒色之徒","认为他天资过人","担心他体弱多病"],"宝玉专抓脂粉钗环，政老爹“便大怒了”，断言“将来酒色之徒耳”，父子隔阂由此有了源头。"]],"cards":[["宝玉那句关于男女的名言是什么？","“女儿是水作的骨肉，男人是泥作的骨肉。”"],["雨村把宝玉归入哪类人？","正邪二气相搏而生，聪俊与乖僻都超出常人的一类。"]],"line":["其聪俊灵秀之气，则在万万人之上","评价一位人才特别突出又特别难管的同事，我会说：聪俊灵秀在万万人之上，乖僻也在万万人之下。"],"tags":["贾府世系","正邪两赋","宝玉"]},"honglou_jinfu":{"intro":"第三回借黛玉的眼睛第一次完整地看贾府：从轿子进门，到外祖母，再到宝玉出场。前一段“步步留心”写初来乍到的孤女，后一段写宝黛初见，宝玉“我曾见过”与摔玉。读时看黛玉怎样观察，宝玉又怎样一出手就把全书的情与玉两条线接上。","focus":["“步步留心，时时在意，不肯轻易多说一句话，多行一步路，惟恐被人耻笑了他去”，十八个字写出寄人篱下的小心。随后的路线是有序的：街市、宁国府匾额、西边角门、垂花门、抄手游廊、穿堂插屏、正房大院，一路只用黛玉所见，不加评论，贾府的规格自然显出来。","宝玉一见黛玉就说“这个妹妹我曾见过的”，贾母笑他胡说，他答“虽然未曾见过他，然我看着面善，心里就算是旧相识”。这句话与第一回的还泪神话对应，在文本内部是对前缘的暗示。","摔玉的缘由是黛玉说“我没有那个”，宝玉便发作。黛玉的心理被写得很准：“因他有玉，故问我有也无”，她是以为宝玉在炫耀；而宝玉的动机恰恰相反：他嫌那玉让人与人不平等，“连人之高低不择”。两人互相误读，是后面许多争吵的原型。"],"notes":[["弃舟登岸","下船上岸"],["垂花门","内院的装饰门"],["抄手游廊","围绕院子的回廊"],["穿堂","前后院之间的过道厅"],["敕造","皇帝下令建造"],["表字","成年后另取的字"],["面善","脸熟"],["杜撰","没有根据地编造"],["罕物","稀罕之物"],["劳什子","讨厌的东西"],["痴狂病","发作时的癫狂劲"],["命根子","最紧要的东西"]],"think":["宝玉摔玉，黛玉以为是炫耀，宝玉是嫌不平等。同一件事为什么会被理解成相反的意思？","因为两人一个在“规矩里”小心揣度，一个在“规矩外”直来直去。黛玉处境敏感，凡事先想别人怎么看自己；宝玉则是以自己的感觉为准。这种错位后文反复出现。"],"quiz":[["黛玉初进贾府“步步留心”的原因是？",["常听母亲说外祖母家与别家不同，怕被人耻笑","担心被门房盘问","不熟悉京城路径"],"原文：“常听得母亲说过，他外祖母家与别家不同”，所以不肯多说一句话、多行一步路。"],["宝玉摔玉时的理由是？",["嫌这玉不能让人人都有，连人之高低不择","生气黛玉不理他","嫌玉太重"],"原文宝玉骂道：“什么罕物，连人之高低不择”。他不满的是玉造成了有玉无玉的高低之分。"]],"cards":[["宝玉初见黛玉说的头一句是？","“这个妹妹我曾见过的。”"],["宝玉给黛玉起的表字是？","“颦颦”。"]],"line":["虽然未曾见过他，然我看着面善，心里就算是旧相识","第一次开会见到新同事，竟觉得投缘，我只能笑说：虽然未曾见过他，然我看着面善，心里就算是旧相识。"],"tags":["宝黛初见","摔玉","贾府空间"]},"honglou_quqian":{"intro":"第五回宝玉在太虚幻境听警幻仙子演唱《红楼梦》十二支曲，每支曲对应一位钗的命运。判词已是主线内容，这里选其中几支曲：一支写宝黛钗的三角，一组写凤姐、巧姐、李纨、可卿，最后以《飞鸟各投林》收束全局。曲词比判词更直白，可当作全书的预告片来读。","focus":["〔终身误〕〔枉凝眉〕合看：“都道是金玉良姻，俺只念木石前盟”，把“金玉”与“木石”两种姻缘摆成对子。“一个是水中月，一个是镜中花”，对宝黛爱情的虚幻性一句判决；“想眼中能有多少泪珠儿”又接回第一回的还泪。","凤姐的曲是《聪明累》，“机关算尽太聪明，反算了卿卿性命”，点出她的能干正是毁掉自己的原因；巧姐的《留余庆》则是另一条线：“忽遇恩人，幸娘亲，积得阴功”，指向后文刘姥姥的报恩；可卿的《好事终》则直说“箕裘颓堕皆从敬，家事消亡首罪宁”，把家败之罪推给宁府。","《飞鸟各投林》是总结：“欠命的，命已还，欠泪的，泪已尽”，“好一似食尽鸟投林，落了片白茫茫大地真干净”。这里的“白茫茫大地”不是个人悲剧，而是整个家族盛衰的归结，与第一回“万境归空”首尾相应。"],"notes":[["金玉良姻","宝钗与宝玉的婚姻"],["木石前盟","黛玉与宝玉的前缘"],["阆苑仙葩","仙境里的花，指黛玉"],["美玉无瑕","指宝玉"],["齐眉举案","夫妻相敬"],["意难平","心中遗憾难消"],["机关算尽","用尽心计"],["卿卿","对所爱的亲昵称呼，此处指凤姐"],["家亡人散","家败人离"],["狠舅奸兄","狠心的舅舅与奸诈的哥哥"],["簪缨","官员的冠饰，代指做官"],["虚名","空名"],["欠泪","还泪之债"],["食尽鸟投林","觅食鸟尽，各自飞散"]],"think":["第五回的曲词几乎把后文都剧透了，为什么读者还会往下读？","因为曲词只给结局与评语，不给过程。作者的用意是把阅读重心从“发生什么”转到“怎样发生”，也让人物在读者心中带着宿命感出场，每个细节都带了重量。"],"quiz":[["“一个是水中月，一个是镜中花”指什么？",["宝玉与黛玉的情感终归虚幻","宝钗与黛玉互相映照","凤姐与可卿的关系"],"这句在〔枉凝眉〕里，前面写“一个是阆苑仙葩，一个是美玉无瑕”，指宝黛。水中月、镜中花都是看得见够不着的东西。"],["《飞鸟各投林》中“欠命的，命已还，欠泪的，泪已尽”回应了哪里？",["第一回绛珠还泪的公案","第三回宝玉摔玉","第二回雨村论正邪"],"“欠泪”指黛玉用一生眼泪偿还灌溉之恩，与第一回对应。"]],"cards":[["“机关算尽太聪明，反算了卿卿性命”写谁？","王熙凤，她的精明反成祸根。"],["《飞鸟各投林》的结句是什么？","“好一似食尽鸟投林，落了片白茫茫大地真干净！”"]],"line":["好一似食尽鸟投林，落了片白茫茫大地真干净！","一个项目的班子散了，群里一条条退群，我想起那句：好一似食尽鸟投林，落了片白茫茫大地真干净。"],"tags":["红楼梦曲","命运预示","金玉木石"]},"honglou_laolao":{"intro":"第六回起，故事从天上落回地面：写一户乡下人家，靠着二十年前的一点连宗关系，派老妇进荣府打秋风。前一段是刘姥姥与女婿狗儿一家的家计盘算，后一段是她进门见到凤姐。读它要看三个细节：算计怎样一步步成形，大家庭的规矩怎样被她用眼睛记下，凤姐怎样“摆谱”。","focus":["刘姥姥的一句“谋事在人，成事在天”，是对女婿一家的劝导，也是她自己的处世观。她拿出的理由很实用：当年连过宗，王夫人“怜贫恤老”，“拔一根寒毛比咱们的腰还粗”。这句比喻既土又准，是穷人对富人的估价方式。","进门的一段全用刘姥姥的眼睛：“咯当咯当的响声，大有似乎打箩柜筛面的一般”，她不认得自鸣钟；周瑞家的与平儿“忙起身”，说明规矩。她看见的只是桌上“碗盘森列，仍是满满的鱼肉在内，不过略动了几样”，那一桌剩饭，已经说明了这家的奢与厚。","凤姐的出场是反着写的：“也不接茶，也不抬头，只管拨手炉内的灰，慢慢的问道：怎么还不请进来？”，先摆足了架子，等刘姥姥“在地下已是拜了数拜”，才“忙欲起身，犹未起身时，满面春风的问好”。这几个“未”字，是对凤姐待人分寸的精确记录。"],"notes":[["谋事在人","事在人为"],["侯门深似海","权贵之家难以接近"],["陪房","陪嫁的仆人"],["利名心","求利图名的心思"],["打嘴现世","自讨没趣丢脸"],["咯当","自鸣钟的声响"],["炕沿","炕的边缘"],["引枕","靠着的枕垫"],["昭君套","一种女用的额饰"],["手炉","暖手的小炉"],["拨手炉内的灰","凤姐拨弄手炉里的炭灰，不急着理客"],["周姐姐","凤姐对周瑞家的称呼"],["弃厌","嫌弃厌恶"],["穷官儿","没有实权的官"],["空架子","只有外表的门面"]],"think":["凤姐为什么先不理刘姥姥，等她拜了才“满面春风”？这对理解凤姐有什么帮助？","因为她要先立住主家的身份，再显得宽厚。这是她懂得“先压后抚”的手段，也暗示她对亲戚往来的真实态度。可与第三回出场的“先闻其声”对照，同样的分寸感贯穿在不同场景中。"],"quiz":[["刘姥姥打算去荣府的主要依据是？",["二十年前与王家连过宗，王夫人为人和善","刘家与荣府有姻亲","周瑞欠她家恩情"],"原文：“当日你们原是和金陵王家连过宗的”，又说王夫人“怜贫恤老”。"],["凤姐见刘姥姥时先“拨手炉内的灰”这个动作透露了什么？",["摆架子，先不显出热情","身体不适","对客人不屑一顾"],"她不接茶不抬头，等周瑞家的已带人进来才满面春风，说明是有意为之。"]],"cards":[["狗儿让刘姥姥进荣府先找谁？","陪房周瑞。"],["“朝廷还有三门子穷亲戚”是谁说的？","凤姐，对刘姥姥说的客套话，也是借此推脱。"]],"line":["拔一根寒毛比咱们的腰还粗","谈到大公司的一点补贴，我对同事说：他们拔一根寒毛比咱们的腰还粗，开口不算太难。"],"tags":["刘姥姥","王熙凤","世态"]},"honglou_gonghua":{"intro":"第七回借周瑞家的送宫花，把荣府内的几处房间串了一遍。选读的两段，一段是薛宝钗讲冷香丸的配方，一段是黛玉收到花后那句带刺的话。两段分别展示宝钗的稳与黛玉的敏，是金玉木石两条线在日常琐事里的并列。","focus":["宝钗讲药方用“可巧”二字：春天白牡丹、夏天白荷花、秋天白芙蓉、冬天白梅花各十二两，还要雨水、白露、霜降、小雪各十二钱。药方里全是“十二”，全看节气，这等于说她的病“要天时凑巧”，也写出她从容、不急不怒的性格。","宝钗对周瑞家的说“再不要提吃药”，随即又详说药方，既不显病弱，也不显得炫耀，是她一贯的分寸。药由“癞头和尚”给，与宝玉的和尚、通灵玉一线并列，暗示金玉的缘分。","黛玉只“就宝玉手中看了一看”，便问是不是单送她一人，听说是各位都有，冷笑一句：“我就知道，别人不挑剩下的也不给我。”这一句不针对周瑞家的，而是针对送花的次序，她敏感的是被排在后面的位置。周瑞家的“一声儿不言语”，说明下人也看得出。"],"notes":[["家常衣服","平日穿的便装"],["海上方","民间秘方"],["胎里带来","先天带来"],["热毒","中医里的热性病因"],["可巧","恰好，指药引要天时凑巧"],["龙眼","龙眼果"],["黄柏","一种中药"],["宫制","宫中制作"],["堆纱","一种纱制的花"],["假花儿","人工制作的花"],["九连环","一种益智玩具"],["冷笑","带讥讽意味的笑"],["挑剩下","别人挑过之后剩下的"],["定省","向长辈问安"]],"think":["同样是送花，宝钗那边是慢慢讲药方，黛玉这边是一句话顶回去。你觉得作者用意是想说谁更好吗？","不是评优劣，而是并置两种气质：宝钗用“知识”和礼数处理关系，黛玉用“感觉”和直觉处理关系。作者没有给出褒贬，只是让两人的处境与性格互相映照。"],"quiz":[["冷香丸的配方为什么强调“可巧”？",["要春夏秋冬四季的花蕊与四个节气的水，需天时凑巧","药材名贵难得","药由和尚亲自制作"],"原文：“东西药料一概都有限，只难得`可巧-二字”，所以连雨水这一天是否下雨都要等。"],["黛玉听说宫花各位都有后，说的那句话表达了什么？",["不满自己被排在“挑剩下”的位置","感谢薛姨妈周到","嫌花样不好"],"“别人不挑剩下的也不给我”，抱怨的是被当作最后一个。"]],"cards":[["冷香丸为谁所制？","薛宝钗，治她从胎里带来的热毒。"],["周瑞家的送宫花最后送到谁手上？","林黛玉，她那时在宝玉房中解九连环。"]],"line":["我就知道，别人不挑剩下的也不给我","领导最后才通知我加入项目，我苦笑着想起黛玉那句：我就知道，别人不挑剩下的也不给我。"],"tags":["薛宝钗","林黛玉","冷香丸"]},"honglou_jinyu":{"intro":"第八回写宝玉到梨香院探望宝钗，两人互看对方的玉与锁，随后黛玉进来，一屋里三个人的关系，在一句话与一只手炉里被点透。第一段是“金玉”的互证，第二段是黛玉对宝玉的“奚落”与对宝钗的暗讽。读时看每句话是如何一语双关的。","focus":["莺儿说宝钗项圈上的两句话“倒象和姑娘的项圈上的两句话是一对儿”，宝玉随即要看。金锁上“不离不弃，芳龄永继”，宝玉念了两遍，又念自己的，笑问“倒真与我的是一对”。这一幕是金玉良缘说的由来，莺儿一句话说破，宝钗“不待说完，便嗔他”，既是害羞，也是防备。","黛玉的“嗳哟，我来的不巧了！”和“要来一群都来，要不来一个也不来”是全书最著名的酸话之一。她没有直接说吃醋，而是用排班式的说法把宝玉和宝钗都堵了回去，宝钗说“我更不解这意”，也是装不懂的回答。","手炉一段是用物件说话：宝玉吃冷酒，宝钗劝他，说得有理，他“便放下冷酒”；黛玉的丫鬟雪雁送手炉，黛玉借题挑拨：“也亏你倒听他的话……比圣旨还快些”。这句话明骂雪雁，实指宝玉刚刚听宝钗的话。宝玉“也无回复之词，只嘻嘻的笑”，说明他听懂了。"],"notes":[["吉谶","吉利的话"],["錾","在金属上雕刻"],["璎珞","项圈，颈饰"],["排扣","一排扣子"],["莺儿","宝钗的丫鬟"],["嗔","责怪"],["杂学旁收","学问杂而不专"],["手炉","暖手小炉"],["奚落","讥讽嘲笑"],["醒脾","提醒使人清醒，这里是李嬷嬷唠叨之意"],["圣旨","皇帝的命令"],["轻狂","轻浮"],["多心","爱猜疑"],["别扫大家的兴","不要败坏众人的兴致"]],"think":["黛玉为何不直接说吃醋，而要绕着说“要来一群都来”？这种说话方式有什么作用？","直说会失体面，而绕着说既表达了不快，又给自己留了余地，对方还无法反驳。这是黛玉语言的特点：用玩笑包着真情，真情被听懂也不丢脸。"],"quiz":[["黛玉借手炉“奚落”谁，针对的是什么？",["宝玉，针对他听宝钗的话","雪雁，嫌她多事","薛姨妈，嫌其招待不周"],"黛玉明说雪雁听紫鹃的话“比圣旨还快些”，实际是暗指宝玉刚听了宝钗劝而放下冷酒。"],["莺儿说的“一对儿”指的是？",["宝钗项圈上的字与宝玉通灵玉上的字","宝钗与黛玉的容貌","宝玉与黛玉的身世"],"莺儿说“和姑娘的项圈上的两句话是一对儿”，指两处八个字。"]],"cards":[["宝钗金锁上的八个字是？","“不离不弃，芳龄永继”。"],["黛玉进门第一句说什么？","“嗳哟，我来的不巧了！”"]],"line":["要来一群都来，要不来一个也不来","周末聚会一个一个迟到，我打趣道：要来一群都来，要不来一个也不来，别零零散散地磨人。"],"tags":["金玉良缘","宝钗黛玉","语言机锋"]},"honglou_jiarui":{"intro":"第十二回写贾瑞迷恋凤姐，被凤姐设局捉弄，最终死在风月宝鉴上。前一段是“毒设相思局”，凤姐用话术把他引入穿堂，让他冻一夜；后一段是跛足道人送镜子，贾瑞正照反照的结局。它既是一段世情小品，也是全书“色空”主题的一次预演。","focus":["凤姐对贾瑞的话是反着听的：“象你这样的人能有几个呢，十个里也挑不出一个来。”表面是称赞，实际是引他入局。她每一句都顺着贾瑞的心思抛饵，又在关键处“放尊重着，别叫丫头们看了笑话”，这样的节奏掌握得非常准。","“穿堂”的一夜写得很实：“东边的门也倒关了”，“关的铁桶一般”，“朔风凛凛，侵肌裂骨”。作者没有评论凤姐，只写贾瑞的狼狈，再接着写他回家被祖父代儒“发狠到底打了三四十扳”，层层加码，惩罚本身比叙述更有说服力。","风月宝鉴“两面皆可照人”，道士说“千万不可照正面，只照他的背面”；贾瑞偏偏先看反面的骷髅，又去照正面的凤姐。镜子里的哭声是点题的一笔：“谁叫你们瞧正面了！你们自己以假为真，何苦来烧我？”，把色欲的虚幻与人的自欺一句挑明。"],"notes":[["酥倒","身心发软"],["饧了眼","眼神迷离"],["纶音佛语","像圣旨与佛语一样令人信服"],["穿堂","前后院间的过道厅"],["过门风","穿堂风"],["朔风凛凛","北风凛冽"],["撒谎","说假话"],["冤业之症","因前世冤孽而得的病"],["褡裢","可搭在肩上的布袋"],["风月宝鉴","镜名，一面是色，一面是骷髅"],["骷髅","人的头骨"],["以假为真","把虚幻当作真实"],["化斋","僧道上门乞食"],["荷包","随身小布袋"]],"think":["贾瑞明知反面是骷髅，为何还要看正面？这个故事想说明什么？","因为欲望并不受提醒支配。道士反复叮嘱，他仍然“再照正面”。作者把批评放在镜子的哭声里：问题在于人把假的当真。这个道理也适用于被虚名虚利牵着走的人。"],"quiz":[["凤姐约贾瑞在穿堂等她，真实目的是？",["捉弄他，让他受冻出丑","与他私会","替贾蓉出气"],"原文写“南北皆是大房墙”，门被关死，让贾瑞“一夜几乎不曾冻死”，是有意设局。"],["风月宝鉴里的“哭声”说明什么？",["人们以假为真，怪不得镜子","镜子被诅咒","道士法力失灵"],"镜内哭道：“谁叫你们瞧正面了！你们自己以假为真”，指出错在人而不在镜。"]],"cards":[["风月宝鉴反面照出的是什么？","一个骷髅。"],["凤姐对贾瑞设下的局叫什么？","相思局。"]],"line":["你们自己以假为真，何苦来烧我？","团队把一份漂亮但失真的数据当成依据，出了事又去怪报表，我想起这面镜子：你们自己以假为真，何苦来烧我？"],"tags":["凤姐","贾瑞","风月宝鉴"]},"honglou_tuomeng":{"intro":"第十三回写秦可卿临终前托梦凤姐，给出两条保家的远虑；第十四回写凤姐受命协理宁国府，第一次当众立威。两段合读，是荣宁盛世里“预警”与“掌权”并置：一个人看见了衰落，另一个人正走上顶点。读时抓住“盛筵必散”和“传齐家人”两处。","focus":["可卿的话先用“月满则亏，水满则溢”“登高必跌重”起势，再落到“树倒猢狲散”，一连用三句俗语把盛衰的道理讲透。她提议“趁今日富贵，将祖茔附近多置田庄房舍地亩”，做祭祀与家塾的固定产业，这是务实的退路，没有玄学。","梦的收尾是“三春过后诸芳尽，各自须寻各自门”，随即“传事云板连叩四下”，凤姐被惊醒，得知可卿已死。作者让托梦与死讯同时到达，凤姐“吓了一身冷汗”，却紧接着是“忙忙的穿衣”，她没有时间消化梦中的警告。","协理一段中，凤姐先“限于明日一早传齐家人媳妇”，再宣布“管不得谁是有脸的，谁是没脸的，一例现清白处理”。分工极细：“这二十个分作两班……这四个人单在内茶房收管杯碟茶器，若少一件，便叫他四个描赔”。她把责任落到人，把时间落到钟点。"],"notes":[["脂粉队里的英雄","称赞女性才干压过男子"],["月满则亏","盈满则缺"],["水满则溢","盛极必衰"],["烈火烹油","形容繁盛到极点"],["鲜花着锦","喻锦上添花"],["盛筵必散","宴席终要散"],["祭祀","祭拜祖先"],["家塾","家族办的私塾"],["云板","传事时敲的铜板"],["点卯","按时点名"],["彩明","凤姐的小厮"],["花名册","人员登记册"],["描赔","照价赔偿"],["徇情","顾及私情不依规矩"]],"think":["秦可卿的预警为什么落在凤姐身上，而凤姐醒来后却没有照做？","因为凤姐当时的位置是“最能做事”的人，所以可卿托付她；但凤姐的处境是要应付眼前的丧事与权力，她眼前的得失压过了远虑。这是人在盛时难以为将来让步的写照。"],"quiz":[["秦可卿托梦提出的保家办法是？",["多置祭祀田产并设家塾，作为败落后的退路","让宁国府分家","请皇帝赐匾"],"原文：“将祖茔附近多置田庄房舍地亩，以备祭祀供给之费皆出自此处，将家塾亦设于此。”"],["凤姐协理宁国府的第一步是什么？",["传齐家人、分派职责、立下规矩","逐个惩罚偷懒的人","向贾珍要对牌然后离开"],"她先要家口花名册，传齐人，然后宣布分工并规定点卯时间。"]],"cards":[["秦可卿托梦所说的两句诗是？","“三春过后诸芳尽，各自须寻各自门。”"],["凤姐立规矩时说“一例现清白处理”是什么意思？","不分有脸没脸，一律按规矩办。"]],"line":["月满则亏，水满则溢","项目接连顺风顺水，我提醒团队多留预案：月满则亏，水满则溢，别等出了事才补救。"],"tags":["秦可卿","王熙凤","盛衰预警"]},"honglou_shicai":{"intro":"第十七回写大观园落成后，贾政带宝玉和一众清客游园题额，实际是一场当面考试。两段选读分别是入园前后的“曲径通幽处”和“有凤来仪”，既写园林题名的学问，也写父子之间“怕”与“才”的拉扯。读时看宝玉的话与贾政反应的错位。","focus":["清客们提的名是“叠翠”“锦嶂”“赛香炉”“小终南”，“只将些俗套来敷衍”，而宝玉答的是“编新不如述旧，刻古终胜雕今”，主张取旧诗“曲径通幽处”。他的立场很明确：与其生造，不如用现成的好句，这是对时人堆砌的批评。","论“翼然”与“泻玉”时，宝玉说“用此等字眼，亦觉粗陋不雅”，因为是省亲别墅，须“蕴籍含蓄”，要符合“应制之例”。他既有诗才，也懂分寸，说话时知道对象与场合，使得这场考试不止是才气，而是判断力。","贾政一边夸一边骂：对宝玉的“有凤来仪”，先说“畜生，畜生”，又说“可谓管窥蠡测矣”。语气是苛的，但对“淇水遗风”“睢园雅迹”都评为“俗”，可见他心里是认同的。他看到农舍时“勾引起我归农之意”，更是文人式的流露，也暗示后文对稻香村的评价。"],"notes":[["清客","依附富贵人家的文士"],["留题","题写匾联"],["编新不如述旧","自己新编不如引用旧诗"],["曲径通幽处","旧诗句"],["应制","应皇帝命令作的诗文"],["蕴籍含蓄","含蓄而不外露"],["颂圣","歌颂皇帝"],["板腐","陈腐刻板"],["管窥蠡测","见识狭小"],["轻薄","轻浮不稳重"],["有凤来仪","凤凰来朝，表示祥瑞"],["归农","回归田园"],["纸折略节","记事的折子"],["天分","天赋"]],"think":["贾政为何对宝玉的话一边骂“畜生”，一边又默认？这是一种怎样的父子关系？","因为他既要保持严父的威势，不愿当众夸奖，又在内心承认宝玉的才情。这种表面严厉、内里认可的矛盾，是中国式家长常见的表达方式，也是宝玉对父亲又敬又怕的来源。"],"quiz":[["宝玉主张用“曲径通幽处”题额，理由是？",["编新不如述旧，旧诗更大方气派","这是自己新作的好句","清客们都已想到这句"],"原文：“编新不如述旧，刻古终胜雕今。况此处并非主山正景，原无可题之处”。"],["宝玉说“淇水遗风”“睢园雅迹”太“板腐”，他提议的是？",["有凤来仪","叠翠","翼然"],"宝玉说：“这太板腐了。莫若`有凤来仪-四字。”"]],"cards":[["贾政这次游园的真实目的之一是什么？","借题额当面试宝玉的才情功课。"],["“编新不如述旧，刻古终胜雕今”是谁说的？","宝玉，主张取用现成旧诗句。"]],"line":["编新不如述旧，刻古终胜雕今","新方案不必处处另起炉灶，把成熟做法拿来用好，也是一种本事：编新不如述旧，刻古终胜雕今。"],"tags":["大观园","贾政宝玉","园林美学"]},"honglou_xingqin":{"intro":"第十八回写元春省亲，是荣国府“烈火烹油”的最高点。选读两段：前一段写灯火辉煌的景象与叙述者的插话，后一段写元春见祖母、母亲与父亲、弟弟的场面。前者是极度的奢华，后者是极度的哀伤，同一回里把两者缝在一起。","focus":["先看景：“水晶玻璃各色风灯”“上面柳杏诸树虽无花叶，然皆用通草绸绫纸绢依势作成”，一场省亲，把冬天装成了春天。叙述者随即跳出来，说“真似暴发新荣之家，滥使银钱”之类“岂《石头记》中通部所表之宁荣贾府所为哉”，这是作者借解释题额来表明自己对奢华的态度。","元春对宝玉的感情被写成“其名分虽系姊弟，其情状有如母子”，她早年“手引口传，教授了几本书，数千字”。后文贾妃见宝玉“泪如雨下”，这一笔有铺垫，不是突然的悲情。","元春对父亲说的话是整个省亲的转折：“田舍之家，虽齑盐布帛，终能聚天伦之乐，今虽富贵已极，骨肉各方，然终无意趣！”最富贵的人说出的最不甘心的话，把全回的繁华翻了一个面。贾政的答话却全是官话，只谈“君恩”，父女之间隔着一层礼法。"],"notes":[["车驾","帝王妃嫔出行所乘的车"],["执拂太监","手持拂尘的太监"],["玻璃世界","形容灯火通明、晶莹如琉璃"],["通草","一种可制假花的植物髓"],["暴发新荣","突然富贵的人家"],["手引口传","亲手引导口头传授"],["呜咽对泣","低声哭泣相对"],["齑盐布帛","咸菜与布帛，指贫寒生活"],["天伦","家人亲情"],["骨肉各方","亲人分隔各地"],["垂帘","隔着帘子"],["草莽寒门","出身寒微的人家"],["国礼","君臣之礼"],["家礼","家人之礼"]],"think":["元春说“骨肉各方，然终无意趣”，这是对富贵的否定吗？还是只是对家庭分离的抱怨？","两者都有。她并未否定富贵，而是承认富贵的代价是失去团聚，这种抱怨是真情，也是对整个体制的暗示：贵妃的荣耀需要骨肉分离来换。可结合第五回《恨无常》类曲词，看她命运的走向。"],"quiz":[["元春对贾政说“终无意趣”，指的是？",["身居富贵却与亲人分隔","宫中礼仪过于繁琐","园中景致不够好"],"她说：“今虽富贵已极，骨肉各方，然终无意趣！”"],["叙述者借题额插话，目的是？",["解释这些题额出自宝玉，也表明对奢华的看法","夸耀贾政的文才","批评宝玉年幼"],"文中说其所拟匾联“在幼童为之，亦或可取”，又有“暴发新荣之家，滥使银钱”之议。"]],"cards":[["元春与宝玉的情分被比作什么？","“有如母子”。"],["元春省亲时说“田舍之家”是想表达什么？","富贵已极却骨肉分离，不如寻常人家团聚。"]],"line":["田舍之家，虽齑盐布帛，终能聚天伦之乐","出差一年回家吃一顿家常饭，我才明白：田舍之家，虽齑盐布帛，终能聚天伦之乐。"],"tags":["元春","省亲","盛极而衰"]},"honglou_huajieyu":{"intro":"第十九回前半，袭人回家后，宝玉去探望，晚上两人说起“赎身”之事；后半写宝玉在黛玉房里午睡时的“耗子精”故事。前一段是怡红院里人与主人的关系，后一段是宝黛之间的亲昵。读时对比袭人“去定了”的说辞与她在家实际说的话，以及宝玉怎样用一个假故事逗黛玉。","focus":["袭人对宝玉的说辞很有章法：先说“我果然是个最难得的”，再把自己放低：“那伏侍的好，是分内应当的，不是什么奇功。我去了，仍旧有好的来了，不是没了我就不成事。”她把话说得全无怨气，却逼得宝玉“竟是有去的理，无留的理”，这是以退为进。","叙述者随即揭出实情：袭人在家里对母兄说“至死也不回去”，“权当我死了，再不必起赎我的念头”。她对宝玉说的“去定了”是有意试探，宝玉赌气说“临了剩我一个孤鬼儿”，说明她这一手触到了他最怕的地方。","黛玉那句“你有玉，人家就有金来配你，人家有`冷香`，你就没有`暖香`去配？”是此前几回金玉之议的回音，说的是宝钗，笑的是宝玉。宝玉随后编“黛山林子洞耗子精”，借“变香芋”的故事逗她，正说到“变了一个最标致美貌的一位小姐”被众耗说“变错了”，句句暗指黛玉。"],"notes":[["赎","用钱换回人身"],["身价","卖身的价钱"],["伏侍","服侍"],["倚势杖贵","依仗权势欺人"],["薄情无义","冷漠无情"],["孤鬼儿","孤零零一个人"],["蠢才","骂人的话，这里是嗔怪"],["暖香","黛玉借“冷香”说的反话"],["诌","随口编造"],["耗子精","老鼠成精"],["令箭","传令用的箭"],["腊八","腊月初八"],["谙练","熟练"],["分身法","分身变化的法术"]],"think":["袭人为什么要对宝玉说“去定了”，而回头又对母兄说“至死也不回去”？这说明她怎样的用心？","她是想借“要走”让宝玉答应几件事，也是在试探自己在他心中的分量。她既不愿真走，又不能直接要求，只能用“退”换“留”。这是一种在主仆关系里不失体面的争取，也说明她比宝玉更清楚自己处境的分寸。"],"quiz":[["袭人对宝玉说“那伏侍的好，是分内应当的，不是什么奇功”，目的是？",["把自己放低，说明自己被赎出去也无妨","夸耀自己的功劳","向宝玉要赏钱"],"她这一段先自谦，再讲不叫去“断然没有”，用平和的话堵住宝玉的挽留。"],["宝玉编耗子精故事的目的是？",["逗黛玉，防她睡出病来","嘲笑扬州风俗","给袭人解闷"],"原文：“宝玉只怕他睡出病来，便哄他道”；故事后半“变一位小姐”又暗指黛玉。"]],"cards":[["袭人在家里对母兄的态度是什么？","“至死也不回去”，叫他们“权当我死了”。"],["黛玉那句“暖香”的话指什么？","指宝钗有“冷香”，宝玉有玉配宝钗的金，嘲弄宝玉。"]],"line":["那伏侍的好，是分内应当的，不是什么奇功","项目验收，客户夸我辛苦，我答：那伏侍的好，是分内应当的，不是什么奇功，别把它当成人情。"],"tags":["袭人","宝黛","怡红院"]},"honglou_pinger":{"intro":"第二十一回里，贾琏偷情后凤姐回来，平儿在两人之间周旋，拿着头发的把柄。选读的两段分别是凤姐当场试探的一幕和凤姐走后平儿与贾琏的对话。要看平儿怎样同时不得罪凤姐又不戳穿贾琏，以及她那句“他醋你使得，你醋他使不得”背后的分寸。","focus":["凤姐的试探是层层逼近的：先问“拿出去的东西都收进来了么”，再问“少什么没有”，最后点出“戒指，汗巾，香袋儿，再至于头发，指甲，都是东西”，一席话说得贾琏“脸都黄了”。她没有证据，却把清单一样样报出，等于把答案递到平儿嘴边。","平儿的回答是教科书式的“答非所问”：“怎么我的心就和奶奶心一样！我就怕有这些个，留神搜了一搜，竟一点破绽也没有。”她用“我的心和您一样”的捧话，把问题变成了自己的功劳。凤姐一句“傻丫头，他便有这些东西，那里就叫咱们翻着了”，既信了她，也在警告她。","凤姐一走，平儿马上变脸：“指着鼻子，晃着头笑道：这件事怎么回谢我呢？”她拿着头发说“这是我一生的把柄了”，贾琏抢过去塞进靴掖，她骂“过了河就拆桥”。这段是平儿唯一不装的时刻，也写出她既护着贾琏又不愿被他拿捏。"],"notes":[["杀鸡抹脖","用手势暗示别说"],["汗巾","腰带或手巾"],["香袋","随身装香的小袋"],["破绽","漏洞"],["把柄","可被利用的把柄"],["靴掖","靴筒里"],["过了河就拆桥","用完就丢"],["促狭","爱捉弄人"],["醋罐","形容爱吃醋的人"],["撒谎","说假话"],["心肝肠肉","亲昵的称呼"],["求欢","求亲热"]],"think":["平儿既要在凤姐面前保贾琏，又要私下向贾琏要谢，这样做是自保还是善意？","两者都有。她替贾琏遮过，是因为一旦败露自己也难脱身；但她没有告发，也有对眼前人的同情。她后来对凤姐、对贾琏都保持“半步之外”，这种分寸是她在这个家里长久自处的方式。"],"quiz":[["平儿对凤姐说“留神搜了一搜，竟一点破绽也没有”的作用是？",["用自己的表白遮过贾琏的事","如实报告所见","嘲讽凤姐多疑"],"她明知有头发在手，却说“一点破绽也没有”，是以自己的口吻掩过。"],["平儿对贾琏说“他醋你使得，你醋他使不得”想表达什么？",["凤姐行得正，贾琏自己有坏心，没资格吃醋","凤姐更爱吃醋","贾琏应该更宠凤姐"],"原文：“他原行的正走的正，你行动便有个坏心”，是在驳贾琏。"]],"cards":[["平儿手中的“把柄”是什么？","贾琏偷情留下的头发。"],["平儿骂贾琏什么？","“过了河就拆桥”。"]],"line":["他醋你使得，你醋他使不得","对方先违规，又责怪我追究，我只想说：他醋你使得，你醋他使不得。"],"tags":["平儿","凤姐","贾琏"]},"honglou_chanji":{"intro":"第二十二回写元宵前后的两件事：湘云看戏时说出“像林妹妹”，引来宝玉、黛玉与湘云之间的小风波；元春送来的灯谜被贾政一首首猜过去，越猜越觉得不祥。前一段是闺阁里的言语分寸，后一段是家长眼里的“谶”，读时看细小的话怎样触发情绪。","focus":["湘云的话本是无心的：“倒象林妹妹的模样儿”。宝玉“忙把湘云瞅了一眼，使个眼色”，湘云却被这个眼色激怒，说“看人家的鼻子眼睛，什么意思！”问题不在话，而在眼色：宝玉怕黛玉恼，湘云觉得是自己被防备。","宝玉的辩解和湘云的反驳，是两种逻辑的撞击。宝玉说“林妹妹是个多心的人”；湘云抓住“别人说他，拿他取笑都使得，只我说了就有不是”。这里作者写的不是谁对谁错，而是宝玉夹在两个女孩子之间的无力，连发誓都显得急切而空洞。","灯谜一段，贾政“愈思愈闷”的依据是谜底：爆竹是“一响而散之物”，算盘“打动乱如麻”，风筝“飘飘浮荡”，海灯“清净孤独”。他随后读到宝钗那首“光阴荏苒须当惜”，更觉“皆非永远福寿之辈”。这是借旁人的眼睛，把元春、迎春、探春、惜春四人的命运先说了一遍，读者此时只当是游戏，回头才知有深意。"],"notes":[["更衣","换衣服"],["眼色","用眼神示意"],["多心","爱多想"],["恶誓","恶毒的誓言"],["辖治","管束"],["爆竹","鞭炮"],["算盘","计算工具"],["风筝","纸鸢"],["海灯","佛前的长明灯"],["荏苒","时间渐渐过去"],["不祥","不吉利"],["福寿","福气与长寿"],["翻来复去","翻来覆去"],["勉强","不情愿地做"]],"think":["湘云一句无心之话，为什么会引出这么大的风波？这对理解黛玉在园中的位置有什么帮助？","因为黛玉是大家都怕惹到的人，所以任何涉及她的玩笑都要谨慎。宝玉的眼色提醒了这点，也让湘云觉得自己被特殊对待。这一幕写出黛玉“被小心对待”的处境，既是特权，也是孤立。"],"quiz":[["贾政读完灯谜后“愈思愈闷”的原因是？",["谜底多是一响而散、飘荡孤独之物，觉得不祥","谜语太难猜","觉得宝玉不用功"],"文中他逐一解读爆竹、算盘、风筝、海灯，认为“此乃一响而散之物”等，皆为不祥之兆。"],["湘云生气的直接原因是？",["宝玉对她使眼色，她觉得被防备","宝玉不肯陪她看戏","黛玉当面嘲笑她"],"她说“看人家的鼻子眼睛，什么意思”，针对的是宝玉那个眼色。"]],"cards":[["贾政猜灯谜时，为什么感到不祥？","谜底爆竹、算盘、风筝、海灯都是散、乱、飘、孤的意象。"],["湘云脱口说戏子像谁？","林黛玉。"]],"line":["光阴荏苒须当惜，风雨阴晴任变迁","新年第一天翻到去年的计划表，我写下一句：光阴荏苒须当惜，风雨阴晴任变迁。"],"tags":["湘云","灯谜","贾政"]},"honglou_xixiang":{"intro":"第二十三回写宝黛在桃花下共读《会真记》，黛玉收花；随后黛玉路过梨香院，听见《牡丹亭》的唱词。前一段是少年男女对禁书的坦率，后一段是黛玉第一次因戏文而“如醉如痴”。读时留意宝玉“藏书”的动作，以及黛玉怎样把几句戏词与旧诗词连在一起。","focus":["宝玉遇见黛玉，先“慌的藏之不迭”，说是《中庸》《大学》；黛玉“趁早儿给我瞧”，一看就“越看越爱看，不到一顿饭工夫，将十六出俱已看完”。作者不写书里写了什么，只写“词藻警人，余香满口”，用读者的感官写出书的魅力，又不越过礼教的边界。","宝玉用书中的“多愁多病身”“倾国倾城貌”戏言，黛玉立刻“带腮连耳通红”，骂他“淫词艳曲”，还要去告诉舅舅舅母。一个是真爱读，一个是真害羞，宝玉连忙发的誓“驮一辈子的碑”，是少年人情急之下的夸张，也使这场吵架带上了喜感。","第二段全写黛玉的听觉：墙内“原来姹紫嫣红开遍，似这般都付与断井颓垣”，她“倒也十分感慨缠绵”；听到“如花美眷，似水流年”，则“不觉心动神摇”。她把眼前戏文与“水流花谢两无情”“花落水流红，闲愁万种”连起来想，这是她以前的阅读与眼前情绪的一次汇合，由此引出“心痛神痴，眼中落泪”。"],"notes":[["中浣","每月中旬"],["会真记","即《西厢记》的前身"],["踟蹰","徘徊不定"],["花冢","埋葬落花的小坟"],["淫词艳曲","旧时对言情戏曲的贬称"],["词藻警人","文辞令人惊艳"],["多愁多病身","《西厢记》里张生的自称"],["倾国倾城貌","《西厢记》里形容莺莺的话"],["姹紫嫣红","形容百花盛开"],["断井颓垣","残破的井和墙"],["如花美眷","如花般美好的人"],["似水流年","像流水一样逝去的时光"],["如醉如痴","沉醉发呆"],["十二个女孩子","梨香院练戏的小戏子"]],"think":["黛玉为什么一边骂宝玉“淫词艳曲”，一边自己“越看越爱看”？这矛盾说明了什么？","她的反应有两层：一是礼教下女孩子必须表现出的羞与怒，二是对词曲之美的真实喜爱。宝玉能看出她“果然有趣”，说明他知道她骨子里喜欢。后文听《牡丹亭》则说明她的阅读已内化为感受。"],"quiz":[["黛玉第一次读《会真记》后的评价是？",["词藻警人，余香满口","文辞粗俗，不足一读","只是闲书，没有意思"],"原文：“自觉词藻警人，余香满口”，她读完还“心内默默记诵”。"],["黛玉听《牡丹亭》唱词时联想到的是？",["旧诗词中“水流花谢”一类的伤春之句","自己的家乡扬州","宝玉刚才的誓言"],"原文：想到“水流花谢两无情”“流水落花春去也”“花落水流红，闲愁万种”，几处凑聚在一起。"]],"cards":[["宝玉被问到所读何书时怎么回答？","“不过是《中庸》《大学》。”"],["黛玉在梨香院外听到的两句唱词是？","“原来姹紫嫣红开遍，似这般都付与断井颓垣。”"]],"line":["原来姹紫嫣红开遍，似这般都付与断井颓垣","看着老厂区拆成平地，我想起那句：原来姹紫嫣红开遍，似这般都付与断井颓垣。"],"tags":["西厢","牡丹亭","黛玉"]},"honglou_mofa":{"intro":"第二十五回，赵姨娘与马道婆合谋，用魇魔法害宝玉与凤姐，前一段写两人的交易，后一段写病重时贾母的暴怒。这是荣府内部矛盾第一次以近乎直白的方式显露：嫡庶之别、利益之争，以及贾母对宝玉的偏爱。读时看马道婆如何一步步引赵姨娘开口。","focus":["马道婆是个高明的“引导者”：先说“你们没有本事”，再装作不知，“阿弥陀佛！你快休问我”，把赵姨娘逼到先开口：“你若教给我这法子，我大大的谢你。”她处处不明说，却让对方自己说出来，这样事成事败责任都不在她。","交易的写法很市井：赵姨娘“写了个五百两欠契来”，“印了个手模”，又拿出“白花花的一堆银子”，马道婆“并不顾青红皂白，满口里应着，伸手先去抓了银子掖起来”。道婆给的是“十个纸铰的青面白发的鬼，并两个纸人”，法术与算账在同一个场景里完成，写尽装神弄鬼之人的贪婪。","第二段的转折在贾母的怒骂。赵姨娘一句“不如把哥儿的衣服穿好，让他早些回去”，被贾母“照脸啐了一口唾沫”。贾母顺势把对贾政的不满也骂了出来：“素日都不是你们调唆着逼他写字念书，把胆子唬破了，见了他老子不象个避猫鼠儿”，说明宝玉的病在她看来也有教育压力的缘故。"],"notes":[["济困扶危","帮助困苦危难中的人"],["欠契","借款凭证"],["手模","按手印"],["梯己","私房钱"],["年庚八字","生辰"],["纸人","用于咒术的纸人"],["熬油费火","彻夜忙碌"],["称愿","称心如愿"],["摘心去肝","形容极端痛心"],["唾沫","口水"],["调唆","挑拨唆使"],["避猫鼠","老鼠见了猫一样害怕"],["棺椁","棺材"],["青红皂白","是非曲直"]],"think":["马道婆为什么始终不肯“明说”？这种说话方式对赵姨娘有什么影响？","因为她要把风险留给对方。赵姨娘主动提出要求、主动许银，就成了“主谋”。这样的话术让人觉得是自己的主意，所以更难回头。作者借此写出一种旧式社会里常见的“推人下水”手段。"],"quiz":[["马道婆从赵姨娘那里得到的东西有哪些？",["一堆银子和五百两欠契","一匹绸缎","一座房产"],"原文写“白花花的一堆银子，又有欠契”，欠契为五百两。"],["贾母为什么骂赵姨娘“烂了舌头”？",["她劝人把宝玉“早些回去”，咒他死","她偷了贾母的东西","她不让宝玉吃药"],"赵姨娘劝“不如把哥儿的衣服穿好”，贾母大怒，骂她盼宝玉死。"]],"cards":[["马道婆给赵姨娘什么法物？","十个纸铰的青面白发的鬼与两个纸人。"],["宝玉凤姐病重时贾母怎样对待赵姨娘？","当众啐骂，说她逼死了宝玉也要她们赔命。"]],"line":["素日都不是你们调唆着逼他写字念书","孩子成绩下滑，家长群里互相指责，我想起这句：素日都不是你们调唆着逼他写字念书，到头来又怪谁呢。"],"tags":["赵姨娘","马道婆","贾母"]},"honglou_dicui":{"intro":"第二十七回前半，宝钗扑蝶，无意在滴翠亭外听见红玉与坠儿私语，急中生智，嫁祸黛玉脱身。这一段是宝钗性格最复杂的一次展示：聪明、周密，又带着几分冷。前一段写听见，后一段写“金蝉脱壳”。读时看她的心理活动与说出口的话怎样完全是两回事。","focus":["扑蝶一段写得轻盈：“玉色蝴蝶，大如团扇”，宝钗“蹑手蹑脚的，一直跟到池中滴翠亭上”。这个形象与后文黛玉葬花对称，两个人一个追蝴蝶，一个埋花；亭子“四面俱是游廊曲桥”，也为后面的“推窗”埋了伏笔。","宝钗听见对话后，心里的第一个念头是“怪道从古至今那些奸淫狗盗的人，心机都不错”。她并不关心对话内容，而是立刻想到“这一开了，见我在这里，他们岂不臊了”。她考虑的是自己是否被牵连，所以“金蝉脱壳”的办法是假装在找黛玉。","她的话说得滴水不漏：“我才在河那边看着林姑娘在这里蹲着弄水儿的”，连细节都有。红玉信以为真，“林姑娘蹲在这里，一定听了话去了”，把一个不在场的人变成了听壁脚的人。宝钗“心中又好笑：这件事算遮过去了，不知他二人是怎样”，这一句把她的冷静与对他人处境的不关心都写出来了。"],"notes":[["玉色蝴蝶","玉色的大蝴蝶"],["蹑手蹑脚","轻手轻脚"],["嘁嘁喳喳","小声说话"],["游廊曲桥","廊与曲折的桥"],["疔","一种毒疮"],["奸淫狗盗","偷偷摸摸的坏事"],["狗急跳墙","逼急了什么都做得出"],["金蝉脱壳","留下假象，自己脱身"],["眼空心大","眼高心大"],["刁钻古怪","精明难缠"],["遮过去","掩饰过去"],["蹲着弄水儿","在水边玩水"]],"think":["宝钗拿黛玉当挡箭牌，这在她是狡猾，还是自保？你会怎样评价？","这是自保，但她选择的是“让别人背”的方式。对黛玉而言，名誉倒未必有损，所以宝钗的判断是“代价小”。这类选择既显出她的周密，也暴露了她在利益冲突时优先自己的一面。作者没有评论，留给读者判断。"],"quiz":[["宝钗听到亭内对话后最先想到的是？",["自己被撞见的后果","红玉的私情","黛玉是否在场"],"她想的是“这一开了，见我在这里，他们岂不臊了”，是怕被牵连。"],["宝钗用来脱身的方法是？",["假说正在追找躲起来的黛玉","直接走开","大声咳嗽提醒"],"她放重脚步，叫道“颦儿，我看你往那里藏！”，造出自己在找人的假象。"]],"cards":[["“金蝉脱壳”指宝钗做了什么？","假装在追黛玉，让红玉以为偷听者是黛玉。"],["宝钗听见亭内说话的是谁？","红玉和坠儿。"]],"line":["今儿我听了他的短儿，一时人急造反，狗急跳墙","老板被逼到墙角，什么话都说得出，我提醒同事：他的短儿被我们听了，一时人急造反，狗急跳墙，别逼得太紧。"],"tags":["薛宝钗","红玉","滴翠亭"]},"honglou_hongse":{"intro":"第二十八回的前后两段：宝玉在冯紫英家的酒席上立令说“女儿悲愁喜乐”，薛蟠接令出丑；回家后宝钗褪红麝串，宝玉看呆，黛玉“呆雁”一嘲。前者写雅俗对照，后者写金玉之议下三人之间的微妙情绪。读时看宝玉“令”里的审美与宝钗眼中的距离。","focus":["宝玉的令是“悲，愁，喜，乐”四字，每字要说出“女儿”。他的“女儿悲，青春已大守空闺。女儿愁，悔教夫婿觅封侯”，用的是闺怨的雅词；冯紫英的“女儿悲，儿夫染病在垂危。女儿愁，大风吹倒梳妆楼”则是民间俚语。雅俗并置，既有笑料，也写出宝玉对女儿处境的敏感。","薛蟠的反应是“说的我通不懂，怎么不该罚”，一句话写出他与宝玉的距离。宝玉接着唱的《红豆曲》“滴不尽相思血泪抛红豆”，铺陈一串“不”字，把情绪推向高处，最后以“雨打梨花深闭门”收酒底，雅得几乎不近人间。","宝钗一段写她的位置：她“总远着宝玉”，因为“金锁是个和尚给的，等日后有玉的方可结为婚姻”。宝玉看到她雪白酥臂，“动了羡慕之心”，转念想“这个膀子要长在林妹妹身上”，一念之差就“呆了”。作者没有责备，写出少年心思的真，同时让黛玉这个“呆雁”之说出场，调侃落在宝玉身上。"],"notes":[["门杯","酒席上第一杯酒"],["青春已大","年纪大了还未嫁"],["封侯","封爵位，指功名"],["红豆","相思的象征"],["无板","不合节拍"],["雨打梨花深闭门","旧诗句，写寂寞"],["红麝串子","用红麝香制的手串"],["酥臂","雪白柔软的手臂"],["妩媚风流","美丽有情致"],["呆雁","傻雁，黛玉戏称宝玉"],["缠绵","纠缠不舍"],["蹬着门槛子","踩着门槛站着"]],"think":["宝钗“总远着宝玉”，却又被宝玉看呆，这个局面里谁更被动？","三个人都被动。宝钗因金锁之说想避嫌却避不开，宝玉想着黛玉却被宝钗的美打动，黛玉用“呆雁”嘲他，也是在掩饰自己的不安。作者不让任何一方占上风，写出这一段关系里互相牵制的状态。"],"quiz":[["冯紫英与宝玉的酒令在风格上的差别是？",["宝玉雅致，冯紫英俚俗","宝玉粗俗，冯紫英雅致","两人风格一样"],"宝玉的“悔教夫婿觅封侯”是闺怨雅词，冯紫英的“儿夫染病在垂危”是民间俚语。"],["“呆雁”是黛玉在说谁？",["宝玉，因他看宝钗的手臂看呆了","宝钗","薛蟠"],"黛玉说“只因听见天上一声叫唤，出来瞧了瞧，原来是个呆雁”，指向看呆的宝玉。"]],"cards":[["宝钗为什么“总远着宝玉”？","因听说“金锁要有玉的方可结婚姻”，怕沾上嫌疑。"],["宝玉酒底说的是哪一句？","“雨打梨花深闭门。”"]],"line":["雨打梨花深闭门","深夜加班后一个人走出大楼，街上一片灯影，脑子里只冒出一句：雨打梨花深闭门。"],"tags":["酒令","金玉","宝钗"]},"honglou_jieshan":{"intro":"第三十回里，宝玉刚和黛玉吵架又和好，随即与宝钗说话时失言，被宝钗反击；后半写宝玉在王夫人身边逗金钏，金钏的一句“金簪子掉在井里头”埋下了第三十二回的伏笔。前一段是话里有话的唇枪舌剑，后一段是一句玩笑最终变成悲剧。读时先看宝钗怎样用“借扇”的话回敬。","focus":["宝玉说“怪不得他们拿姐姐比杨妃，原来也体丰怯热”，是开玩笑，却冒犯了宝钗。宝钗“冷笑了两声”，回敬：“我倒象杨妃，只是没一个好哥哥好兄弟可以作得杨国忠的！”她既没有失态，也一句话让宝玉哑口。","随后靛儿来找扇子，宝钗借题发难：“你要仔细！我和你顽过，你再疑我。”她明着骂靛儿，其实是借此发作，作者让读者看见她“大怒”后用话收回来。黛玉得意地插话问“你听了两出什么戏”，宝钗答“李逵骂了宋江，后来又赔不是”，明显是暗指刚才宝玉向黛玉赔不是的事，宝玉黛玉“早把脸羞红了”。","金钏一段有两层。表面是逗趣：宝玉往她口中塞“香雪润津丹”，说“我明日和太太讨你”。金钏回“金簪子掉在井里头，有你的只是有你的”，是一句俗话，意思是“早晚是你的，不必急”，却被王夫人当场听见，立刻“照金钏儿脸上就打了个嘴巴子”。后文金钏投井，使这句话成为谶语。"],"notes":[["奚落","讥讽"],["体丰怯热","身体丰满怕热"],["杨国忠","杨贵妃的族兄，此处是宝钗的反讽"],["搭讪","找话说"],["造次","鲁莽"],["嘻皮笑脸","不庄重地玩笑"],["通今博古","通晓古今"],["负荆请罪","背着荆条向人认错"],["心里有病","心里有愧"],["生分","疏远"],["香雪润津丹","清热生津的丸药"],["巧宗儿","占便宜的机会"],["嘴巴子","耳光"],["下作","下流"],["撵出去","赶出去"]],"think":["宝钗的“冷笑”与“借扇”都没有大发作，却让宝玉黛玉脸红。你觉得这是智慧还是锋芒？","两者都有。她的锋芒藏在合乎礼数的语言里，让人说不出错。读者能看见她的“气”，却抓不到“过”。这也是后来黛玉与她的距离：宝钗不会失态，而黛玉常常失态。"],"quiz":[["宝钗被宝玉比杨妃后的回敬是？",["只是没一个好哥哥好兄弟可以作得杨国忠的","是我不懂杨妃","我没有杨妃那样的身份"],"她的原话：“我倒象杨妃，只是没一个好哥哥好兄弟可以作得杨国忠的！”"],["金钏说“金簪子掉在井里头，有你的只是有你的”是什么意思？",["早晚是你的，不必急","金簪掉进井里了","让宝玉去捞"],"这是一句俗话，劝宝玉别急。但被王夫人听见，成了她被撵的原因，也在后文成谶。"]],"cards":[["宝钗借靛儿找扇子发的火，指向谁？","宝玉，因他刚才奚落她。"],["金钏被撵的直接原因是什么？","王夫人醒来听见她与宝玉的对话。"]],"line":["我倒象杨妃，只是没一个好哥哥好兄弟可以作得杨国忠的","同事开玩笑说我“比某某强”，我笑着回：我倒象杨妃，只是没一个好哥哥好兄弟可以作得杨国忠的，这话您可别再提。"],"tags":["宝钗","金钏","语言机锋"]},"honglou_shanzi":{"intro":"第三十一回，晴雯撕扇、湘云来到、黛玉说“金麒麟”，几件事各自独立，又彼此牵连。前一段是宝玉与晴雯、麝月的闺房玩笑，后一段是黛玉把宝玉与湘云的亲近翻成一句酸话。读时看宝玉那段“爱物”的理论怎样被晴雯一句“拿扇子来我撕”接住。","focus":["宝玉的“爱物”论既荒诞又合他的性情：“你要撕着玩也可以使得，只是不可生气时拿他出气。”他把物件的价值放在使用者的心情上，而不是物本身，所以“千金难买一笑，几把扇子能值几何”。晴雯“最喜欢撕”，答得干脆；麝月一句“少作些孽罢”，是旁观者的体面。","撕扇的“响”被反复写：“嗤的一声，撕了两半，接着嗤嗤又听几声”，宝玉说“响的好，再撕响些”。这场笑闹是把前一天晴雯被他责怪、受委屈的情绪消解掉的方式，用“撕”来替代“骂”，是宝玉对丫鬟的另一种体贴。","黛玉的“他不会说话，他的金麒麟会说话”是第三十一回的暗线：湘云因戴着金麒麟，被黛玉暗刺；偏偏宝钗在场“抿嘴一笑”，使宝玉自觉说错话，宝钗反应也成了一种态度。接着湘云与翠缕谈“阴阳”，是借侍女口气转入下一回。"],"notes":[["爱物","珍惜并善待物件"],["嗤的一声","撕扇的声响"],["少作些孽","劝她别糟蹋东西"],["千金难买一笑","古语，指为博一笑不惜花费"],["开心儿","取乐"],["乘凉","夏夜纳凉"],["宽衣","脱外衣"],["抿嘴","闭着嘴微笑"],["楼子花","花瓣层叠的荷花"],["气脉充足","精气充沛"],["翠缕","湘云的丫鬟"],["小丫头","年纪小的丫鬟"]],"think":["宝玉那套“爱物”的说法有道理，还是替自己的放纵找理由？你怎么看？","既有道理也有软肋。道理在于东西本为人所用，用得痛快比束之高阁更合其用；软肋在于这套说法只有在不缺物的人家才成立。所以它的魅力来自宝玉的天真，也透出他不识人间艰难的底色。判断时可以对照后文贾府的败落。"],"quiz":[["宝玉允许晴雯撕扇的前提是？",["不要在生气时拿东西出气","必须是旧扇子","必须得到袭人同意"],"原文：“你要撕着玩也可以使得，只是不可生气时拿他出气。这就是爱物了。”"],["黛玉说“他的金麒麟会说话”，针对的是？",["宝玉对湘云的亲近，暗指金玉之说","湘云的口才","宝钗的聪明"],"黛玉冷笑，指的是湘云有金麒麟，与宝玉有玉，借“金”字暗刺“金玉”之议。"]],"cards":[["麝月看晴雯撕扇说了一句什么？","“少作些孽罢。”"],["晴雯最喜欢做什么？","撕扇子，听那一声响。"]],"line":["你要撕着玩也可以使得，只是不可生气时拿他出气","压力大时我允许自己发泄，但提醒自己：你要撕着玩也可以使得，只是不可生气时拿他出气。"],"tags":["晴雯","爱物","金麒麟"]},"honglou_jinqian":{"intro":"第三十二回里，宝玉对黛玉说“你放心”，被袭人在无意中听见；同一回，金钏投井，王夫人与宝钗议论她的后事。前一段是全书最接近直说的一次情话，后一段是一个丫鬟的死被处理成“发送”。两件事在同一回里，写的是爱与生死的两种分量。","focus":["宝玉先说“你放心”三个字，黛玉装作不懂；宝玉解释：“你皆因总是不放心的原故，才弄了一身病。”黛玉听后“如轰雷掣电”，“竟有万句言语，满心要说，只是半个字也不能吐”。双方都说不出口，因为两人都知道一旦出口就改变了关系。","随后宝玉在袭人面前“好妹妹，我的这心事，从来也不敢说”的失神，被袭人听见，“吓得魄消魂散”，自思“令人可惊可畏”。作者借袭人的视角，让读者看到宝黛私情在园里是可能被人读出的危险，同时也预示她后来的“告密”。","金钏一段，王夫人说“谁知他这么气性大，就投井死了”，口吻是自责，但话里仍把责任推在“气性大”；宝钗劝慰“他并不是赌气投井”，又主动献出自己的衣服，说“我从来不计较这些”。她的体贴周全，让王夫人安心，却也把一个丫鬟的死处理成了“不为可惜”。"],"notes":[["拭泪","擦眼泪"],["造次","鲁莽"],["肺腑","内心"],["轰雷掣电","形容受到强烈震撼"],["魄消魂散","吓得失魂落魄"],["中了邪","鬼迷心窍"],["憨顽","不知轻重地玩耍"],["妆裹","给死者穿衣入殓"],["发送","料理丧事"],["忌讳","避讳不吉利"],["不为可惜","不值得可惜"],["念念于兹","总记着这件事"],["罪过","过错"],["慈善人","心地善良的人"]],"think":["宝钗劝王夫人“他并不是赌气投井”，是真心宽慰，还是在回避责任？你怎么判断？","两者可能并存。她要缓解王夫人的负疚，所以用“失脚”解释；但同样的话也抹去了金钏的主体：一个丫鬟的死被说成“糊涂人”“不为可惜”。作者不替她辩护，也不加评论，留给读者判断。"],"quiz":[["宝玉说“你放心”三个字，意思是？",["让黛玉不必担心他会改变心意","让黛玉放心身体","让黛玉放心学业"],"他解释“你皆因总是不放心的原故，才弄了一身病”，说的是情意之事。"],["袭人听见宝玉对“妹妹”说的话后的反应是？",["吓得魄消魂散，担心将来出事","替他们高兴","立刻去告诉王夫人"],"原文：“吓得魄消魂散”，又“令人可惊可畏”，担心的是难免不才之事。"]],"cards":[["金钏是怎么死的？","被王夫人撵出后投井。"],["宝钗拿自己的什么送给金钏装殓？","两套新做的衣服。"]],"line":["你皆因总是不放心的原故，才弄了一身病","朋友老是焦虑失眠，我只想说：你皆因总是不放心的原故，才弄了一身病，试着把事情交出去。"],"tags":["宝黛","金钏","王夫人"]},"honglou_songpa":{"intro":"第三十四回里，宝玉挨打后让晴雯送两条旧帕给黛玉，黛玉心领神会，一夜“五内沸然炙起”；同一回写宝钗与薛蟠母子的一场风波。前一段是不言之情，后一段是家人间的冲突。读时看“旧帕”怎样既不说话又说尽，以及宝钗劝兄时的分寸。","focus":["宝玉对晴雯的吩咐很有意思：“没有什么可说的”，却要人去看一看；晴雯问“怎么搭讪”，他便拿两条旧手帕。“你放心，他自然知道”，这是他对黛玉的信任，也是对自己情意的承认。礼物不重要，重要的是它“不对”的程度，把关系推到只有两人懂的层面。","黛玉的反应经历了“发闷”“大悟”，随后心里“可喜”“可悲”“可笑”“可惧”“可愧”五层转换。作者不写眼泪，而写“五内沸然炙起”，这是最接近内心的描写，也预示后文她在帕子上题诗。旧帕是私相传递的物，所以连“可惧”都算在内。","薛家一段写宝钗劝兄：“是你说的也罢，不是你说的也罢，事情也过去了，不必较证。”她把事情的是非放在一旁，只问后果，这是她处理冲突的典型态度。薛蟠“一生见不得这样藏头露尾的事”，一怒就“抓起一根门闩来就跑”。两人性格对比，写出这家人的脆弱。"],"notes":[["搭讪","找个借口开口"],["白眉赤眼","没有缘由"],["撂","扔"],["打趣","取笑"],["神魂驰荡","心神激荡"],["五内沸然","五脏如沸，形容心潮翻涌"],["调唆","挑唆"],["窥度","私下揣测"],["有口难分","有口难辩"],["青红皂白","事情的是非"],["较证","对质争辩"],["藏头露尾","遮遮掩掩"],["献勤儿","讨好"],["门闩","插门的横木"]],"think":["宝玉送旧帕为什么不亲口说，也不写字？这种“不说”有什么好处与风险？","好处是只有彼此能懂，避开旁人，也避开直接表白的负担；风险是靠猜，一旦黛玉会错意，就会产生更大的误会。黛玉这一次“大悟”，说明两人已有足够默契，但这种默契也正是后文反复误会的来源。"],"quiz":[["黛玉看见旧帕后心里想到的是？",["宝玉懂我的苦意，既可喜又可悲","宝玉在敷衍她","宝玉送错东西"],"原文列了“可喜”“可悲”“可笑”“可惧”“可愧”五层感受。"],["宝钗劝薛蟠时，重点放在哪里？",["事情已过去，不必争是非，以后少胡闹","一定要查出是谁说的","让他向宝玉道歉"],"她说：“是你说的也罢，不是你说的也罢，事情也过去了，不必较证。”"]],"cards":[["宝玉送给黛玉的是什么？","两条半新不旧的旧手帕。"],["薛蟠听说有人说是他告的状时有什么反应？","急得乱跳，抓起门闩要去打宝玉。"]],"line":["是你说的也罢，不是你说的也罢，事情也过去了，不必较证","复盘会上有人只想追责，我提议：是你说的也罢，不是你说的也罢，事情也过去了，先谈后面怎么办。"],"tags":["旧帕","宝黛","薛蟠"]},"honglou_lianye":{"intro":"第三十五回里宝玉养伤，一碗莲叶羹引出玉钏与宝玉的一段对话，随后他请莺儿打络子，说起宝钗。前一段是宝玉哄玉钏消气，后一段是丫鬟之间的闲话。一个关于金钏之死留下的情绪，一个关于金玉未来的暗示，读时看宝玉怎样用温存和玩笑化解气氛。","focus":["玉钏是金钏的妹妹，她“满脸怒色，正眼也不看宝玉”。宝玉的做法是“变尽方法，将人都支出去”，再陪笑问长问短，凭她“怎么丧谤，他还是温存和气”，玉钏渐渐“脸上方有三分喜色”。这一段把宝玉对丫头的“低姿态”写得极细，也让玉钏的怨气有出口。","莲叶羹的细节很会写人：宝玉故意说“不好吃”，玉钏“赌气尝了一尝”，才发觉被哄；她骂“不用和我甜嘴蜜舌的，我可不信这样话”，其实已经软了。作者让一碗汤成为化解怨恨的工具，也提醒读者金钏的死在这个家里仍留着余波。","莺儿络子的一段是另一种笔墨：“大红的须是黑络子才好看的，或是石青的才压的住颜色”，“松花配桃红”，“葱绿柳黄是我最爱的”。她对色彩的判断精准，写的是手艺人的专业；而“明儿宝姐姐出阁，少不得是你跟去了”，是宝玉无心的一句，后来成了现实。"],"notes":[["陪笑","脸上带笑"],["丧谤","挖苦讥讽"],["哭丧","一脸哭相"],["扎挣","勉强支撑"],["现世现报","当场应验的报应"],["甜嘴蜜舌","说好听的话"],["络子","用丝线编成的装饰网"],["汗巾子","腰带"],["松花","黄绿色"],["葱绿","嫩绿色"],["攒心梅花","一种络子花样"],["方胜","两个菱形相叠的图案"],["朝天凳","络子花样名"],["拗口","读起来不顺"],["出阁","出嫁"]],"think":["宝玉哄玉钏吃汤，是诚心赔罪，还是习惯性的体贴？这对理解他有什么帮助？","两者兼有。他确实因金钏之事自责，但哄人的方式又是他一贯的温存与玩笑。这种“对谁都好”使他有魅力，也让他的歉意显得不够沉重，读者可以体会他在情感上的天真与限制。"],"quiz":[["玉钏对宝玉最初的态度是？",["满脸怒色，正眼也不看他","热情招呼","漠不关心"],"原文：“玉钏儿满脸怒色，正眼也不看宝玉”，因为金钏之事。"],["莺儿建议大红汗巾子配什么络子？",["黑色或石青色","白色","金色"],"莺儿说：“大红的须是黑络子才好看的，或是石青的才压的住颜色。”"]],"cards":[["莲叶羹一段里，玉钏被哄的方法是什么？","宝玉说汤不好吃，她赌气尝了一口才发觉被哄。"],["莺儿原名叫什么？","金莺，姑娘嫌拗口才叫莺儿。"]],"line":["不用和我甜嘴蜜舌的，我可不信这样话","对方一连串漂亮承诺，我只回一句：不用和我甜嘴蜜舌的，我可不信这样话，先看交付。"],"tags":["玉钏","莺儿","宝玉"]},"honglou_mengzhao":{"intro":"第三十六回，宝玉午睡，宝钗在旁绣鸳鸯，黛玉与湘云路过窗外，宝玉梦中喊出“我偏说是木石姻缘”。后一段写宝玉去梨香院听龄官唱曲，却被龄官冷落，又看见贾蔷哄她。两段都是“被看见”的时刻：宝钗听见了梦话，宝玉看清了别人的专情。","focus":["窗外一幕是用动作写态度：黛玉“连忙把身子一藏，手握着嘴不敢笑出来”，湘云“忽然想起宝钗素日待他厚道，便忙掩住口”。两个女孩子的反应一对比，黛玉爱取笑，湘云顾念厚道，各有性格。黛玉“冷笑了两声”，说明她心里已看明白。","宝玉的梦话是全书对“金玉姻缘”最直接的否定：“和尚道士的话如何信得？什么是金玉姻缘，我偏说是木石姻缘！”宝钗“不觉怔了”，接着转问袭人“他们没告诉你什么话”，既不接话，也不追问。她的沉默是自处的方式，不让这句梦话变成事实。","龄官一段与前面形成对照。宝玉“素习与别的女孩子顽惯了的”，却被龄官一句“嗓子哑了”拒绝，他“从来未经过这番被人弃厌，自己便讪讪的红了脸”。贾蔷提着雀儿笼来哄龄官，宝玉“把听曲子的心都没了，且要看他和龄官是怎样”，从被拒绝到成为旁观者，是他认知上的一次转折。"],"notes":[["蝇帚子","驱蝇用的拂尘"],["针线","缝纫刺绣的活计"],["纱窗","糊纱的窗"],["不让人","不饶人"],["厚道","宽厚"],["玩话","玩笑话"],["怔","发呆"],["金玉姻缘","宝钗与宝玉的婚姻之说"],["木石姻缘","黛玉与宝玉的前缘"],["惬怀","称心"],["文风不动","一动不动"],["弃厌","嫌弃"],["讪讪","难为情的样子"],["变弄","想办法弄来"],["袅晴丝","《牡丹亭》里的一套曲"]],"think":["宝玉梦中喊“我偏说是木石姻缘”，宝钗听见却不接话。如果你是宝钗，会有什么感受？她这样处理合适吗？","她会既尴尬又清醒，因为这是对她身份的否定，却发生在梦里，无法反驳。她选择不接话、转开话题，是保护自己也保护宝玉的做法。这符合她一贯的“不争”，但也说明她对结局已有判断。"],"quiz":[["宝玉在梦中喊的话是？",["什么是金玉姻缘，我偏说是木石姻缘","我不要娶宝钗","黛玉才是我的知己"],"原文：“和尚道士的话如何信得？什么是金玉姻缘，我偏说是木石姻缘！”"],["龄官为什么拒绝给宝玉唱曲？",["她嗓子哑了，也不愿迎合别人","她与宝玉有仇","她要先给贾蔷唱"],"她回答：“嗓子哑了。前儿娘娘传进我们去，我还没有唱呢。”表明不唱即使是娘娘也不曾唱的。"]],"cards":[["黛玉与湘云在窗外看到什么？","宝玉睡着，宝钗坐在身旁做针线。"],["贾蔷拿什么哄龄官？","一只会衔旗串戏台的玉顶金豆雀儿。"]],"line":["什么是金玉姻缘，我偏说是木石姻缘","团队里大家都说这样搭配最合适，我心里嘀咕一句：什么是金玉姻缘，我偏说是木石姻缘，合不合适得自己试过才知道。"],"tags":["梦兆","宝钗","龄官"]},"honglou_haitang":{"intro":"第三十七回，探春发帖起社，众人各取别号，随后以“咏白海棠”限韵作诗。选读两段，前一段是取号时的互相打趣，后一段是诗作与评议。读时看诗社怎样用别号定下每个人的“人设”，以及宝钗、黛玉两首诗被李纨评为“含蓄浑厚”与“风流别致”。","focus":["取号时，探春自称“蕉下客”，黛玉随即说“古人曾云蕉叶覆鹿，他自称蕉下客，可不是一只鹿了？快做了鹿脯来”。探春立刻回击，给黛玉起了“潇湘妃子”，理由是“他住的是潇湘馆，他又爱哭”。笑闹之间，每人的号都成了对其性格的玩笑。","评诗一段是全回的核心。宝钗诗的颈联“淡极始知花更艳，愁多焉得玉无痕”，用意含蓄；黛玉诗“偷来梨蕊三分白，借得梅花一缕魂”，意象更奇。李纨的评语是：“若论风流别致，自是这首，若论含蓄浑厚，终让蘅稿。”并列了两种标准，也预示以后诗社里两人的位置。","评议中李纨“依我评论，不与你们相干，再有多说者必罚”，既是评判者也是社规的制定者；探春说“就叫个海棠社罢。虽然俗些，因真有此事，也就不碍了”，把社名也落在眼前事上。这个诗社的运作规则，在这几句话里已经定下。"],"notes":[["别号","字之外的雅号"],["居士","在家修行的人，也是文人自称"],["稻香老农","李纨的号"],["蕉下客","探春的号"],["蕉叶覆鹿","典出《列子》的寓言"],["潇湘妃子","黛玉的号"],["娥皇女英","舜的二妃"],["斑竹","竹上有斑点"],["蘅芜君","宝钗的号"],["手瓮","手捧的瓮"],["苔盆","长苔的盆"],["白帝","秋神"],["婷婷","姿态美好"],["太真","杨贵妃道号"],["西子","西施"],["缟袂","素色的衣袖"],["风流别致","风韵独特"],["含蓄浑厚","意蕴深厚"],["压尾","排在最后"],["限韵","规定用什么韵"]],"think":["李纨说宝钗“含蓄浑厚”，黛玉“风流别致”，你觉得这两个评语在日后会怎样影响两个人？","评语既是诗评，也是性格评语：宝钗以稳重取胜，黛玉以才情取胜。两个标准没有高下，但在“含蓄浑厚”被推为第一时，黛玉“风流别致”的评价更像一种补偿。这个微妙的位置差，正是她们之间若即若离的关系的缩影。"],"quiz":[["黛玉用“蕉叶覆鹿”取笑探春，是借什么意思？",["“蕉下客”像一只鹿，可以做成鹿脯","探春喜爱芭蕉","探春的字里有鹿"],"她说：“他自称蕉下客，可不是一只鹿了？快做了鹿脯来。”"],["李纨对宝钗与黛玉诗的评价分别是？",["宝钗含蓄浑厚，黛玉风流别致","宝钗风流别致，黛玉含蓄浑厚","两人一样好"],"原文：“若论风流别致，自是这首，若论含蓄浑厚，终让蘅稿”，前者指黛玉，后者指宝钗。"]],"cards":[["“潇湘妃子”的号是谁起的？","探春，因黛玉住潇湘馆、爱哭。"],["李纨为诗社定下的开社日子？","每月初二、十六。"]],"line":["淡极始知花更艳，愁多焉得玉无痕","看完一场过于喧闹的发布会，我反而更喜欢那种淡极始知花更艳的朴素。"],"tags":["海棠社","宝钗黛玉","诗社"]},"honglou_juhua":{"intro":"第三十八回，诗社第二次聚会，题是菊花，黛玉以《咏菊》《问菊》《菊梦》三首夺魁；宝钗又作《螃蟹咏》，讽刺世人。选读的两段，一段是菊花诗的几首（咏、画、问），一段是螃蟹咏的颈尾联及大家的评。读时看黛玉“满纸自怜”和宝钗“皮里春秋”两种不同的诗心。","focus":["黛玉的《咏菊》“满纸自怜题素怨，片言谁解诉秋心”，是以菊自比：自己的孤独与无人理解。《问菊》的“孤标傲世偕谁隐，一样花开为底迟？”进一步把问号抛给菊花。宝钗的《画菊》则是“诗余戏笔不知狂，岂是丹青费较量”，是游戏的口吻，自视才高而不张扬。","螃蟹咏里宝钗写：“眼前道路无经纬，皮里春秋空黑黄。”前一句讽螃蟹横行无章法，后一句讽人表面无心、实则暗存褒贬，“空黑黄”指蟹黄的黑与黄。众人读到这里“不禁叫绝”，宝玉说“我的诗也该烧了”。这是借小题目寄大讽刺。","评语也有层次：“这些小题目，原要寓大意才算是大才，只是讽刺世人太毒了些”，既认可才华，又对其锋芒有保留。末联“于今落釜成何益，月浦空余禾黍香”则把螃蟹落入锅中的结局，转成对“横行者”下场的感慨，两句下得很重。"],"notes":[["无赖诗魔","诗兴缠人"],["欹石","斜倚的石头"],["素怨","无声的怨"],["秋心","秋日的心事"],["陶令","陶渊明"],["平章","品评，这里指陶渊明咏菊定了菊的品格"],["孤标傲世","品格高傲、不合流俗"],["东篱","陶渊明采菊之处，借指菊圃"],["皮里春秋","心中有褒贬而不言"],["寓大意","以小题寄托大意"],["绝唱","最佳之作"],["积冷","寒气积聚"],["落釜","下锅"],["禾黍","五谷，这里借典寄兴亡之叹"]],"think":["宝钗的螃蟹咏被评为“讽刺世人太毒了些”，这与她平日的稳重有什么冲突吗？","没有冲突，反而是互补。她平日“不露锋芒”，诗是她唯一可以“说重话”的地方。这种把锋芒收在诗里的方式，说明她对自己的话分得清场合。读者可由此看出稳重背后的另一面：有判断，也有不满。"],"quiz":[["黛玉《咏菊》中“满纸自怜题素怨”表达的是？",["以菊自比，自怜孤独","赞美菊花品格","描写重阳聚会"],"她在诗里写“满纸自怜”，把自己的怨与秋心都放进去，是借咏物自抒怀抱。"],["“皮里春秋空黑黄”讽刺的是什么？",["表面平静、内心实有褒贬的人","螃蟹肉少","食蟹的人太多"],"“皮里春秋”指心里有褒贬而不说，与“眼前道路无经纬”并用，讽刺世人。"]],"cards":[["螃蟹咏里的名句是？","“眼前道路无经纬，皮里春秋空黑黄。”"],["谁的《咏菊》夺魁？","林黛玉。"]],"line":["满纸自怜题素怨，片言谁解诉秋心","夜里翻看自己多年前的日记，那一页写满自怜，我想：满纸自怜题素怨，片言谁解诉秋心，原来都是写给自己看的。"],"tags":["菊花诗","螃蟹咏","黛玉宝钗"]},"honglou_yapai":{"intro":"第四十回，贾母带刘姥姥逛大观园，宴上鸳鸯行牙牌令，刘姥姥“女大王”式的凑趣，凤姐、鸳鸯合伙捉弄她。前一段是鸳鸯宣布令规、几位小姐太太依次对令，后一段是刘姥姥的“花儿落了结个大倭瓜”与套杯的圈套。读时看雅令与俗答的落差，以及笑声下贾府对她的利用。","focus":["鸳鸯的令是“骨牌副儿”：先说三张牌，再合成一个名字，要求“无论诗词歌赋，成语俗话，比上一句，都要叶韵”。贾母的“头上有青天”“六桥梅花香彻骨”“一轮红日出云霄”，信口而来；湘云的“日边红杏倚云栽”“闲花落地听无声”，是典型的诗书闺秀。每个人的答语恰是各自学识的显示。","鸳鸯开令前先说：“酒令大如军令，不论尊卑，惟我是主。”一个丫鬟当众立规，却无人反驳。这显示她在贾母身边的地位，也预示后文她的抗婚。同时刘姥姥想溜，鸳鸯喝令“拉上席去”，一场乡下老太太的“被迫参与”已经开始。","刘姥姥答令“花儿落了结个大倭瓜”，引得“哄堂大笑”。随后凤姐、鸳鸯联手：先说木杯，再换竹根，最后搬出“黄杨根整抠的十个大套杯”，要“灌他十下子”。刘姥姥自己心里明白：“不过诓我多喝两碗。”她一边被取笑，一边装傻配合，是个懂得趁势而为的老人。"],"notes":[["酒令大如军令","酒令一旦定下不容违抗"],["骨牌副儿","骨牌组合"],["叶韵","押韵"],["蓬头鬼","骨牌的一个组合名"],["钟馗","传说中捉鬼的神"],["门杯","第一杯酒"],["倭瓜","南瓜"],["黄杨根","黄杨木的根"],["套杯","大小成套的杯子"],["竹根","竹子的根"],["灌他十下子","逼着喝"],["哄堂大笑","满屋人一齐笑"],["诓","哄骗"],["半推半就","不完全推辞也不完全接受"]],"think":["刘姥姥明知被取笑，却仍然配合，这是愚笨还是聪明？作者怎样评价她？","是聪明。她明白贾府要的是一个“逗趣的人”，自己要的是一份实惠，彼此心照不宣。作者写她“诓我多喝两碗”的内心，是在告诉读者她并不傻。这种自觉的“卑微”使她在后来的救巧姐时，显出分量。"],"quiz":[["鸳鸯说的“酒令大如军令”是什么意思？",["令一旦定下，不分尊卑，一律遵守","令要像军令一样快","酒令比军令更难"],"原文：“酒令大如军令，不论尊卑，惟我是主。违了我的话，是要受罚的。”"],["刘姥姥心里认为木头杯的提议是什么？",["凤姐等不过是想哄她多喝两碗","真有木头杯的传统","小孩子玩具"],"她想：“想必是小孩子们使的木碗儿，不过诓我多喝两碗。”"]],"cards":[["刘姥姥答令的那句话是？","“花儿落了结个大倭瓜。”"],["鸳鸯的令是什么？","骨牌副儿：说三张牌，再合成名，须押韵。"]],"line":["酒令大如军令，不论尊卑，惟我是主","会议主持人开场就说：规则大如军令，不论尊卑，惟我是主，谁也别打断别人发言。"],"tags":["牙牌令","刘姥姥","鸳鸯"]},"honglou_miaoyu":{"intro":"第四十一回，贾母一行到栊翠庵，妙玉请宝钗、黛玉到耳房吃“梯己茶”，宝玉随后赶来；刘姥姥用过的杯子，妙玉要丢弃，宝玉另有安排。两段写妙玉的洁癖与宝玉的体贴，读时看她对钗、黛、宝玉三个人的不同待法。","focus":["妙玉用的杯子有等级：给宝钗的是“晋王恺珍玩”“宋元丰五年四月眉山苏轼见于秘府”的古玩，给黛玉的是形似钵而小的“点犀”，给宝玉的是自己常用的“绿玉斗”。宝玉说“我就是个俗器了”，妙玉答“只怕你家里未必找的出这么一个俗器来呢”，既护着自己的清高，又收了宝玉的恭维。","品茶的议论是妙玉的“茶道”：“一杯为品，二杯即是解渴的蠢物，三杯便是饮牛饮骡了。”黛玉问“旧年的雨水？”，妙玉“冷笑道：你这么个人，竟是大俗人，连水也尝不出来”。这里妙玉的傲慢与洁癖尽出，对黛玉也毫不客气，只有对宝玉才“十分欢喜”。","成窑杯的去留是人物的试金石。妙玉说“若我使过，我就砸碎了也不能给他”，对刘姥姥的鄙视显露无遗；宝玉接过话：“那茶杯虽然脏了，白撂了岂不可惜？依我说，不如就给那贫婆子罢，他卖了也可以度日。”他既不责备妙玉，又替姥姥想了出路，用一个“不如”化解了冲突。"],"notes":[["梯己茶","私下的小范围茶会"],["成窑","明代成化窑的瓷器"],["耳房","正房旁的小房"],["蒲团","打坐用的垫子"],["风炉","烧水煮茶的炉"],["世法平等","佛教语，众生平等"],["随乡入乡","入乡随俗"],["蟠虬","盘曲的虬龙"],["一杯为品","品茶只一杯"],["饮牛饮骡","比喻粗鄙的牛饮"],["糟踏","浪费"],["授受","递给与接受"],["山门","寺庙的大门"],["贫婆子","穷老太太"],["小幺儿","小厮"]],"think":["妙玉对宝玉“十分欢喜”，对黛玉却冷笑，这种差别对待说明什么？","说明她看人以“同类”与“俗人”划线：宝玉知她的洁癖，也肯顺着她说话；黛玉直问“旧年的雨水”，在她看来是不会品味。这也是妙玉的局限：清高有门槛，容易把有才的人当成“俗人”。作者并不褒贬，只是让她的行为说话。"],"quiz":[["妙玉不要那只成窑杯的原因是？",["刘姥姥用过，嫌脏","杯子裂了","杯子太旧"],"文中：“知为刘姥姥吃了，他嫌脏不要了”，并说“若我使过，我就砸碎了也不能给他”。"],["宝玉怎样解决成窑杯的难题？",["建议送给刘姥姥，她卖了可以度日","替妙玉砸碎它","劝妙玉留着"],"宝玉说：“不如就给那贫婆子罢，他卖了也可以度日。”"]],"cards":[["妙玉的饮茶三杯论是什么？","“一杯为品，二杯即是解渴的蠢物，三杯便是饮牛饮骡了。”"],["给宝玉用的杯子是什么？","妙玉自己常用的绿玉斗。"]],"line":["一杯为品，二杯即是解渴的蠢物，三杯便是饮牛饮骡了","咖啡馆里朋友点了第三杯，我笑着说：一杯为品，二杯即是解渴的蠢物，三杯便是饮牛饮骡了。"],"tags":["妙玉","品茶","洁癖"]},"honglou_fengyu":{"intro":"第四十五回，黛玉在宝钗劝过之后，主动向宝钗坦白心事；晚上风雨，她写下《秋窗风雨夕》，宝玉披着蓑衣来探。前一段是两个人关系的转折点，后一段是黛玉最典型的孤独与宝玉最典型的体贴。读时看黛玉怎样把“多心”说成“误”，宝钗又怎样回答。","focus":["黛玉开口先认错：“我最是个多心的人，只当你心里藏奸”，随后承认“往日竟是我错了，实在误到如今”。她把话说到“我母亲去世的早，又无姊妹兄弟，我长了今年十五岁，竟没一个人象你前日的话教导我”，是第一次以孤女的身份向人坦白，不再用玩笑遮掩。","燕窝粥的顾虑，写出寄人篱下的小心：“我又兴出新文来熬什么燕窝粥，老太太，太太，凤姐姐这三个人便没话说，那些底下的婆子丫头们，未免不嫌我太多事了。”她算的是下人的眼光。宝钗先笑她“将来也不过多费得一副嫁妆罢了”，再说“你放心，我在这里一日，我与你消遣一日”，用玩笑与承诺同时安抚她。","《秋窗风雨夕》通篇用“秋”字回环：“已觉秋窗秋不尽，那堪风雨助凄凉”，一句里叠了四个“秋”；“不知风雨几时休，已教泪洒窗纱湿”则是泪眼里写到的风雨。宝玉“头上带着大箬笠，身上披着蓑衣”进来，黛玉“不觉笑了：那里来的渔翁！”，作者让一阵笑，打破了诗里的凄凉，写出宝玉在她生活里的位置。"],"notes":[["多心","爱猜疑"],["藏奸","心怀不良"],["杂书","正经书之外的书"],["不受用","心里不舒服"],["燕窝粥","补品"],["兴出新文","另弄出新花样"],["虎视耽耽","形容暗中盯视"],["言三语四","说长道短"],["同病相怜","处境相同而互相同情"],["司马牛之叹","《论语》中司马牛感叹无兄弟"],["秋窗","秋天的窗"],["箬笠","竹叶编的斗笠"],["蓑衣","草编的雨衣"],["渔翁","打鱼的老人"],["棠木屐","棠木制的木屐"]],"think":["黛玉在这一回里为什么会向宝钗敞开心扉？这个转变对后来两人的关系有什么影响？","因为宝钗没有借机攻讦她，反倒劝她读书、关心她的病，这使黛玉意识到自己的猜疑是“误”。从此两人有了真诚的友谊，但也只是友谊的层面，涉及宝玉时仍有隔阂。这一回可视为两人关系的最亲密时刻。"],"quiz":[["黛玉自陈不愿煮燕窝粥的主要顾虑是？",["怕婆子丫头们嫌她事多","药费太贵","宝钗不会同意"],"她说：“那些底下的婆子丫头们，未免不嫌我太多事了”，因她“原是无依无靠投奔了来的”。"],["宝玉冒雨探黛玉，黛玉见他打扮后说的是？",["那里来的渔翁","你怎么又来了","雨天不该出门"],"原文：“黛玉不觉笑了：那里来的渔翁！”因宝玉戴箬笠披蓑衣。"]],"cards":[["《秋窗风雨夕》里最著名的一句是？","“已觉秋窗秋不尽，那堪风雨助凄凉！”"],["宝钗对黛玉说的“同病相怜”指什么？","两人都不像宝玉等人那样有完整的家庭依靠。"]],"line":["已觉秋窗秋不尽，那堪风雨助凄凉","深夜独自在酒店，窗外风雨不停，我想起：已觉秋窗秋不尽，那堪风雨助凄凉。"],"tags":["宝钗黛玉","秋窗风雨夕","孤独"]},"honglou_yuanyang":{"intro":"第四十六回，贾赦要娶鸳鸯为妾，邢夫人、鸳鸯的嫂子、哥哥轮番劝说，鸳鸯当众骂嫂子，又在贾母面前铰发发誓。前一段是在园中痛骂嫂子，后一段是对着众人的决绝。读时抓住鸳鸯的三种语言：对嫂子的泼辣、对众人的陈词、对贾母的哭诉。","focus":["鸳鸯骂嫂子的话很有力度：“怪道成日家羡慕人家的丫头做了小老婆，一家子都仗着他横行霸道的，一家子都成了小老婆了！”她把被人称羡的“做姨娘”拆成一条利益链，又说“我若得脸呢，你们外头横行霸道，自己封就了自己是舅爷；我要不得脸败了时，你们把忘八脖子一缩，生死由我去！”两头都算到了。","贾赦的话是另一种逼法：“自古嫦娥爱少年”“凭他嫁到了谁家，也难出我的手心”。他只给两条出路，要么做妾，要么“终身不嫁男人”。他的话经金文翔转述，更显得家长以权力把一个丫鬟的命运框死。","鸳鸯的回应是行动先于语言：“袖内带了一把剪子”，当着众人“打开头发就铰”，已“剪下半绺来了”。她说“别说是宝玉，就是宝金、宝银、宝天王、宝皇帝，横竖不嫁人就完了！就是老太太逼着我，一刀子抹死了，也不能从命！”一连四个“宝”字，是把对方的猜疑全数堵回去。贾母那句“我通共剩了这么一个可靠的人”，写出她对鸳鸯的依赖。"],"notes":[["天大的喜事","嫂子的反话，指做妾"],["眼热","羡慕嫉妒"],["小老婆","妾"],["横行霸道","仗势欺人"],["火炕","比喻苦海"],["舅爷","对娘舅家人的称呼"],["忘八脖子","骂人话，指缩头"],["嫦娥爱少年","旧诗句，此处是贾赦自嘲"],["手心","势力范围"],["支吾","应付搪塞"],["疔","毒疮，这里是发誓用语"],["绺","一缕头发"],["当姑子","出家做尼姑"]],"think":["鸳鸯抗婚为什么选择“铰发”而不是辩解？这样做有哪些代价和优势？","因为她的身份没有辩解的空间，唯有用身体做证明。代价是可能被贾赦报复，优势是当众让此事变成无法回避的公共事件，借贾母的庇护解围。她的刚烈来自对处境的清醒判断，不是一时冲动。"],"quiz":[["鸳鸯向嫂子骂出“把我送在火炕里去”的意思是？",["她们羡慕做妾的好处，却把她推入苦海","她们要送她去火炕取暖","她要搬到别的院"],"她把“做小老婆”说成利益链，认为嫂子等人是把她推向火炕。"],["鸳鸯当着众人发誓的方式是？",["铰下头发，并说宁死也不从命","跪地磕头求饶","离家出走"],"她“袖内带了一把剪子”，“打开头发就铰”，并说“一刀子抹死了，也不能从命”。"]],"cards":[["贾赦逼鸳鸯的话中，哪句最狠？","“凭他嫁到了谁家，也难出我的手心”，不嫁人也不放过。"],["贾母听后说了什么？","“我通共剩了这么一个可靠的人，他们还要来算计！”"]],"line":["一刀子抹死了，也不能从命","被逼着在原则上让步时，我心里只有一句话：一刀子抹死了，也不能从命。"],"tags":["鸳鸯","抗婚","贾赦"]},"honglou_xiangling":{"intro":"第四十八回，香菱拜黛玉为师学诗，先谈读王维、陶渊明的心得，再被宝玉、探春拉进话题，宝玉还吹嘘自己的稿子被外人抄去。两段写香菱最明朗的一面，也写出大观园对“笔墨流传”的态度。读时看她怎样用生活经验解释诗的好处。","focus":["香菱一开口就是诗论：“诗的好处，有口里说不出来的意思，想去却是逼真的。有似乎无理的，想去竟是有理有情的。”她举“大漠孤烟直，长河落日圆”，说“直”字似无理，“圆”字似太俗，但“合上书一想，倒象是见了这景的”。她用感官解释诗，不依赖理论。","她又举“渡头余落日，墟里上孤烟”，用自己上京时“那个烟竟是碧青，连云直上”的亲见去印证。读后“倒象我又到了那个地方去了”，这说明她的领会来自生活，而不是书卷，所以黛玉才说“这话有了些意思”。","第二段的转折在宝玉“把稿子给他们瞧”：探春黛玉的反应是“我们的笔墨也不该传到外头”。宝玉却道：“古来闺阁中的笔墨不要传出去，如今也没有人知道了。”这是宝玉与女孩们在“诗与名”上的分歧，也让香菱的“只是心里羡慕”显得更有分量。"],"notes":[["红圈","在诗上圈点的标记"],["杜律","杜甫的律诗"],["领略","体会"],["滋味","味道"],["逼真","真切"],["无理","不合情理"],["橄榄","比喻回味悠长"],["湾住船","把船停在岸边"],["三昧","精髓"],["会心","心领神会"],["化出来","由前人诗句化用而来"],["柬","请帖"],["入社","加入诗社"],["自暴自弃","自己看轻自己"],["诌","随口编"]],"think":["香菱学诗这一回为什么被许多读者视为全书最温暖的章节之一？","因为它展示一个本是被拐卖、被命名的人，在读诗中第一次有了自己的感受与判断。她不是靠身份获得尊重，而是靠对诗的领会。同时作者也让这份喜悦与她的命运反差：这样的明亮，更显得后面的结局可怜。"],"quiz":[["香菱觉得“直”“圆”二字的妙处是什么？",["似无理实则逼真，合上书一想像亲见其景","直与圆是常用字","它们押韵好听"],"她说：“这`直-字似无理，`圆-字似太俗。合上书一想，倒象是见了这景的。”"],["宝玉说的“稿子”被外人抄去，探春黛玉的态度是？",["认为闺阁笔墨不该传到外头","替他高兴","要求他再多送几份"],"原文：“便是成诗，我们的笔墨也不该传到外头。”"]],"cards":[["香菱喜欢的“余”“上”二字出自哪联？","“渡头余落日，墟里上孤烟”。"],["黛玉把这句诗的来源指向谁？","陶渊明的“暖暖远人村，依依墟里烟”。"]],"line":["诗的好处，有口里说不出来的意思，想去却是逼真的","读完一份很短的财报，我想起香菱那句：诗的好处，有口里说不出来的意思，想去却是逼真的，数字也有它说不出的东西。"],"tags":["香菱","学诗","黛玉"]},"honglou_luxue":{"intro":"第四十九、五十回写大观园的一场雪：先是湘云、平儿等在芦雪庵烤鹿肉，随后众人拈阄联句，凤姐开了个“粗话”的头。前一段写热闹与名士风，后一段写诗社的规则与技艺。读时看湘云那句“是真名士自风流”与凤姐“一夜北风紧”各代表怎样的诗观。","focus":["烤鹿肉是对“雅”的挑战：“我吃这个方爱吃酒，吃了酒才有诗”，湘云把吃肉说成作诗的前提。黛玉打趣“今日芦雪庵遭劫”，湘云立刻反驳：“是真名士自风流，你们都是假清高，最可厌的。我们这会子腥膻大吃大嚼，回来却是锦心绣口。”她把不拘小节说成真才华，把拘谨说成假清高。","宝钗的话也有分寸：“你回来若作的不好了，把那肉掏了出来，就把这雪压的芦苇子……上些，以完此劫。”这是玩笑，也是一种约束：吃得放肆，作得要好。几个人的不同气质一并写出：湘云豪放，黛玉挑剔，宝钗稳。","联句一开始由凤姐起句：“想下雪必刮北风，昨夜听见一夜的北风，我有一句，这一句就是`一夜北风紧`。”众人的评语是“这句虽粗，不见底下的，这正是会作诗的起法”，因为它“留了写不尽的多少地步与后人”。这是作者借众人之口说出诗法：起句平实，余地才大。"],"notes":[["年例","按惯例发放的年节钱物"],["斗篷","披风"],["凫靥裘","用野鸭颈毛做成的皮衣"],["罕事","少见的事"],["腥膻","荤腥"],["作践","糟蹋"],["遭劫","遭受劫难"],["假清高","装出的清高"],["锦心绣口","文思华美"],["拈阄","抓阄"],["联道","联接下一句"],["粗话","朴素的话"],["起法","起句的方法"],["地步","余地"],["花子","乞丐"]],"think":["凤姐不识字，却“开了头”并被夸为“会作诗的起法”，这说明什么？","说明诗的起句重在自然真切，不在学问。凤姐用日常观察说出“一夜北风紧”，既诚实又为后文留下空间。这也写出凤姐的另一面：她不是文人，却有直觉。作者借此提醒读者，诗法并不神秘。"],"quiz":[["湘云说“是真名士自风流”针对的是？",["黛玉等人嫌她吃鹿肉不雅","宝琴披着凫靥裘","平儿丢了镯子"],"她说“你们都是假清高，最可厌的”，为自己大吃大嚼辩护。"],["众人为什么称赞凤姐那句“一夜北风紧”？",["句子虽粗，却为后面留了余地，是会作诗的起法","辞藻华丽","对仗工整"],"原文：“这句虽粗，不见底下的，这正是会作诗的起法。”"]],"cards":[["联句的第一句是谁说的？","凤姐，“一夜北风紧”。"],["芦雪庵烧烤鹿肉的主人是谁带头？","史湘云，与平儿一起。"]],"line":["想下雪必刮北风，昨夜听见一夜的北风","写报告开头别绕，平实起笔就行，像凤姐那句：想下雪必刮北风，昨夜听见一夜的北风。"],"tags":["湘云","联句","凤姐"]},"honglou_qiaoyunqiu":{"intro":"第五十二回，宝玉的孔雀裘被手炉火星烧了个洞，外头匠人都不敢接，病中的晴雯硬撑着补好。前一段写她挣命补裘，后一段写补完后的症状与宝玉的愧疚。读时看晴雯“说不得，我挣命罢了”这句，以及叙述者如何交代她病体的缘由。","focus":["先看“难题”的写法：“不但能干织补匠人，就连裁缝绣匠并作女工的问了，都不认得这是什么，都不敢揽。”一件衣服能难倒全城匠人，等于告诉读者这是稀罕物，也为晴雯的手艺垫了一层。","晴雯的反应是倔：“拿来我瞧瞧罢。没个福气穿就罢了。这会子又着急。”口气像在顶嘴，实际是主动。“这是孔雀金线织的……界线”，她立刻看出可行的办法；宝玉劝她，她回一句“不用你蝎蝎螫螫的”，把关切顶回去。人物的“嘴硬心软”一句话写足。","补成之后“已使的力尽神危”，“满眼金星乱迸”，是前面“恨命咬牙挨着”的后果。王太医说“今日如何反虚微浮缩起来”，宝玉叹“都是我的罪孽”，晴雯却在枕上说“好太爷！你干你的去罢”，仍是平常口气。作者不让她喊疼，也不替她叹息，这样更让人心疼。"],"notes":[["褂子","外套"],["手炉","暖手的小炉"],["织补","补织破处"],["揽","承接"],["孔雀金线","孔雀羽毛捻成的线"],["界线","一种补织针法"],["挣命","拼了命"],["蝎蝎螫螫","形容唠叨紧张"],["金星乱迸","头昏眼花"],["力尽神危","精疲力竭"],["疏散驱邪","发散外邪的药"],["益神养血","补养气血"],["罪孽","过错"],["痨病","肺痨"],["净饿","旧时伤风时以断食养病"]],"think":["晴雯明知自己病重，仍要补裘，是出于对宝玉的情意，还是为了证明自己？","两者并存。她说“没个福气穿就罢了”，是自尊；又说“怕宝玉着急”，是情意。她不愿被看作无用之人，在这件事上找到“只有我能做”的位置。这个位置也让她后来的被逐显得更让人不平。"],"quiz":[["全城匠人为什么不敢接补裘的活？",["没人认得这件衣服的料子，不敢揽","衣服太贵","主人不在"],"原文：“都不认得这是什么，都不敢揽。”"],["晴雯回答宝玉劝阻时的态度是？",["嫌他唠叨，坚持自己补","感激并停手","让麝月代做"],"她说“不用你蝎蝎螫螫的，我自知道”。"]],"cards":[["雀金裘是用什么织成的？","孔雀金线。"],["晴雯补完裘后身体状况如何？","力尽神危，头重身轻，需请大夫调养。"]],"line":["说不得，我挣命罢了","明早要交的稿子，我对自己说：说不得，我挣命罢了，写完再睡。"],"tags":["晴雯","雀金裘","病中"]},"honglou_jizu":{"intro":"第五十三回写荣宁二府年关的两件事：乌进孝送来庄子的租子，贾珍嫌少；除夕在宁国府祭宗祠，排场极盛。账目的紧张与礼仪的奢华相对，作者没有评论，只用数字和陈设说话。读时看贾珍怎样算账，以及“只剩了八九个庄子”这句背后的预兆。","focus":["乌进孝的话很有分寸：“托爷的福，还能走得动”，说到年成则一口气说出“从三月下雨起，接接连连直到八月……九月里一场碗大的雹子”。贾珍却说“我算定了你至少也有五千两银子来，这够作什么的！”一个讲灾，一个讲账，两种语言互不相让。","贾珍的算盘里有一句暗点：“如今你们一共只剩了八九个庄子，今年倒有两处报了旱涝。”庄子数目在减少，收入不够，而他又说“比不得那府里，这几年添了许多花钱的事”，这句话直指省亲之后的花费，也让读者预感到“入不敷出”。","祭宗祠一段，作者用物件写排场：“象鼻三足鳅沿鎏金珐琅大火盆”“猩红毡”“黑狐皮的袱子”“大白狐皮坐褥”。贾母却说“你这里供着祖宗，忙的什么似的，那里搁得住我闹”，轻轻一句，把热闹里的疲惫点了出来。前一段的收入不足与这里的陈设有余，形成一种沉默的对照。"],"notes":[["打擂台","争着做同样的事，这里指与贾珍较劲少交"],["硬朗","身体硬实"],["庄子","田庄"],["旱涝","旱灾与水灾"],["雹子","冰雹"],["饥荒","债务"],["年例","年节例行的开支"],["脸皮厚些","不顾面子"],["红毡","红色毡毯"],["珐琅","一种釉"],["引枕","靠枕"],["坐褥","坐垫"],["妯娌","兄弟的妻子"],["铜脚炉","暖脚的铜炉"],["暖阁","有暖气的小间"]],"think":["贾珍说“我算定了你至少也有五千两银子来”，他为什么对租子多少如此在意？这反映了什么？","因为府里支出巨大而收入固定，每一笔庄租都是现金流。他的在意并非贪心，而是账面真实压力。作者借他的口把“盛世的账”摆出来：排场需要钱，而收入在缩，这是衰败最现实的原因。"],"quiz":[["乌进孝说年成不好的理由是？",["春夏多雨，九月又有大冰雹","被盗贼抢了","官府加税"],"原文：“从三月下雨起，接接连连直到八月，竟没有一连晴过五日。九月里一场碗大的雹子。”"],["贾珍说“如今你们一共只剩了八九个庄子”，意味着？",["田庄越来越少，收入减少","他要卖掉庄子","庄子都改了名字"],"他是在算账、抱怨，说明家业已经在缩。"]],"cards":[["乌进孝送来的租单让贾珍感到什么？","太少，贾珍原以为至少五千两银子。"],["贾母为什么不肯在宁国府吃晚饭？","因为这里忙着祭祀，不想添乱，吃的东西让人送去。"]],"line":["如今你们一共只剩了八九个庄子","年底盘点资产，发现可用的只剩一小半，我想起贾珍那句：如今你们一共只剩了八九个庄子。"],"tags":["乌进孝","宗祠","家业"]},"honglou_tanchun":{"intro":"第五十六回，探春在凤姐病中代理家务，发现月例与脂粉钱重复，又要把园子里的竹子、香料、菜蔬承包出去。选读的两段，一段是三人（探春、李纨、宝钗）与平儿商议“兴利”，一段是宝钗对分派人选的建议。读时看探春如何抓小事，宝钗如何“小惠全大体”。","focus":["探春发现的是一笔重复账：“一月有二两月银外，丫头们又另有月钱……头油脂粉，每人又是二两。”平儿的解释很内行：“姑娘们的每月这二两，原不是为买这些的”，是为临时用钱。她再说买办迟交、“买的不是正经货”，是官中之弊。探春从小事看出系统的漏洞，这是她理家的路径。","宝钗对婆子们的评语是“幸于始者怠于终，缮其辞者嗜其利”，一句话评尽“争着揽差事”的人心。探春的分派具体到“老祝妈……代代都是管打扫竹子”“老田妈本是种庄稼的”，都是按所长派人，而不是按关系派人。","宝钗在最后的“让”最见分寸：莺儿的娘擅长弄香草，平儿提议，宝钗却说“断断使不得”，转推“怡红院有个老叶妈”，并解释“那是他们私情儿，有人说闲话，也就怨不到咱们身上了”。她不要利益，不要嫌疑，用“至公”换得全体人的认可。"],"notes":[["分例","按等级规定的用度"],["月银","每月的银钱"],["买办","府里负责采购的人"],["搪塞","应付"],["脱空","落空"],["善开交","好了结"],["妥当","稳妥可靠"],["稻稗","稻与稗草"],["利息","收益"],["在行","内行"],["私情儿","私下的人情"],["至公","最公平"],["看小了","小看"],["诚实","老实可靠"]],"think":["探春改革从“小事”入手，是策略还是性格？这与凤姐的理家方式有什么差别？","两者兼有。探春细心、讲理，所以从重复的账目下手，容易让人信服；凤姐则重权威与威慑。这两种方式各有利弊：探春的更公平，但阻力来自既得利益者；凤姐的更快，但常靠人情。作者让二人对照，写出贾府治理的难处。"],"quiz":[["平儿对探春解释那“二两月银”的真实用途是？",["临时用钱，不是买脂粉","买衣服","付给下人"],"平儿说：“姑娘们的每月这二两，原不是为买这些的，原为的是一时当家的奶奶太太或不在……偶然一时可巧要几个钱使。”"],["宝钗为什么不赞成请莺儿的娘管香草？",["怕被人说自己带私人，改推老叶妈","莺儿的娘手艺差","她嫌价格太高"],"她说“断断使不得”，推荐叶妈并说“怨不到咱们身上了”，是为避嫌。"]],"cards":[["宝钗评婆子们的话是什么？","“幸于始者怠于终，缮其辞者嗜其利。”"],["探春发现的重复支出是什么？","月银二两之外，又有每人二两的头油脂粉钱。"]],"line":["那是他们私情儿，有人说闲话，也就怨不到咱们身上了","团队内部推荐人选，我主动回避：那是他们私情儿，有人说闲话，也就怨不到咱们身上了。"],"tags":["探春","宝钗","理家"]},"honglou_zijuan":{"intro":"第五十七回，紫鹃为试探宝玉，说黛玉要回苏州，宝玉当场痴病发作，贾母等人赶来，知是“顽话”。前一段是紫鹃与宝玉的对话，后一段是宝玉的痴态与贾母、薛姨妈的反应。读时看紫鹃怎样设计，以及宝玉的反应如何把“宝黛”的关系推到众人面前。","focus":["紫鹃进门不直说，先说宝玉“赌气跑了这风地里来哭”，再顺着燕窝的话题聊开。宝玉为黛玉向贾母“略露了个风声”，才有每日一两燕窝，这件事被紫鹃问出来，既是谢意，也是试探。“你妹妹回苏州家去”是在这个氛围里轻轻抛出的一句，宝玉“吃了一惊”。","宝玉的反应是“死也不放”，说“要去连我也带了去”。他原来的话也很有逻辑：“苏州虽是原籍，因没了姑父姑母，无人照看”。但情感压过理性，所以一听到“林”字就“满床闹起来”。这是一个把“怕失去”写成病症的场面。","贾母说“你又知道他有个呆根子，平白的哄他作什么”，薛姨妈则说：“宝玉本来心实，可巧林姑娘又是从小儿来的……这会子热刺刺的说一个去，别说他是个实心的傻孩子，便是冷心肠的大人也要伤心。”长辈们明白，也容忍这层关系，这是后文婚姻选择里的重要背景。"],"notes":[["小蹄子","对小丫头的骂称，含亲昵"],["呆根子","傻气的人"],["实心","老实认真"],["顽话","玩笑话"],["哄","哄骗"],["万安","平安"],["热刺刺","突然、急切"],["冷心肠","无情之人"],["托实","过于依赖"],["露了个风声","透露了消息"],["扯谎","说谎"],["白话","空话"],["燕窝","补品"],["赌气","因不满而任性"],["风地","迎风的地方"]],"think":["紫鹃为什么要拿“回苏州”试宝玉？她是替谁在试探？","她是替黛玉试探。她担心黛玉没有依靠，想看宝玉是否真心。她用的是最简单也最冒险的方法，结果证明宝玉真心，但也让他病倒、让贾母等人知道了这层感情。作者用这个事件把宝黛关系公开化，同时增加了后文的压力。"],"quiz":[["紫鹃试探宝玉的方式是？",["说黛玉要回苏州家去","说黛玉要出嫁","说黛玉病重"],"原文：“你妹妹回苏州家去。”宝玉当即“吃了一惊”。"],["薛姨妈为什么说“冷心肠的大人也要伤心”？",["宝黛从小一处长大，忽听要分开，谁都难过","她要劝黛玉别走","她认为宝玉应该娶宝钗"],"她说：“他姊妹两个一处长了这么大，比别的姊妹更不同。”"]],"cards":[["宝玉听到“林”字后的反应是？","满床闹起来，说“林家的人接他们来了，快打出去罢！”"],["宝玉为黛玉做的“燕窝”这件事怎么办成的？","他在贾母面前略露了风声，贾母吩咐凤姐每日送一两燕窝。"]],"line":["这会子热刺刺的说一个去，别说他是个实心的傻孩子，便是冷心肠的大人也要伤心","被临时通知要调走的同事，我劝慰他：这会子热刺刺的说一个去，别说他是个实心的傻孩子，便是冷心肠的大人也要伤心。"],"tags":["紫鹃","宝黛","试探"]},"honglou_yeyan":{"intro":"第六十二回写湘云醉卧芍药茵，第六十三回写怡红院群芳夜宴占花名。前一段是全书最美的一幅画面，后一段是用签文给每个人下的“小判词”。读时先看湘云醉眠的画面感，再看签文怎样既是游戏又暗含各人归宿。","focus":["湘云醉眠一段像一帧油画：“四面芍药花飞了一身，满头脸衣襟上皆是红香散乱，手中的扇子在地下，也半被落花埋了，一群蜂蝶闹穰穰的围着他，又用鲛帕包了一包芍药花瓣枕着。”她口中“犹作睡语说酒令”，念的是“醉扶归，却为宜会亲友”，醉意、美景与她的豪爽性情融成一体。醒后“心中反觉自愧”，还有分寸。","签文的写法是双层的：探春抽到杏花，“日边红杏倚云栽”，注“得此签者，必得贵婿”，她“红了脸”，说“这原是外头男人们行的令”。众人以“我们家已有了个王妃”打趣，掩过去。李纨抽到老梅，“竹篱茅舍自甘心”，只自饮一杯；麝月抽到荼蘼，注“在席各饮三杯送春”，宝玉“愁眉忙将签藏了”，表明他听出了散席的意思。","黛玉一句“`夜深`两个字，改`石凉`两个字”，是笑湘云白日醉卧石凳，把签诗里的“夜深花睡去”改成“石凉”，和上一段形成呼应。作者把游戏玩笑写得自然，让读者在热闹里悄悄看到“春尽”的预兆。"],"notes":[["红香散乱","花瓣与红色衣物散乱"],["鲛帕","薄纱手帕"],["闹穰穰","热闹纷扰"],["醉扶归","酒令中的词句"],["扎挣","勉强撑起"],["酽茶","浓茶"],["醒酒石","含在口中解酒的石子"],["掣","抽取"],["瑶池仙品","签上的题字"],["贵婿","身份高贵的女婿"],["劳什子","讨厌的东西，这里是戏称"],["霜晓寒姿","老梅的题字"],["香梦沉酣","海棠签的题字"],["韶华胜极","春光最盛"],["连理枝头花正开","香菱签上的诗句"]],"think":["签文既是游戏，又是预言。你觉得这种“游戏里的预言”在小说里有什么作用？","它让读者在轻松场景里感受到宿命，增加回读时的回味；也让人物对命运的反应有了戏剧性：探春红脸、宝玉藏签，都说明每个人在玩笑中隐约知道自己的结局。这种写法比直接讲道理更含蓄，也更有余味。"],"quiz":[["探春抽到的签文内容是？",["杏花，必得贵婿","老梅，自饮一杯","海棠，不便饮酒"],"原文：“一枝杏花，那红字写着`瑶池仙品`四字……`日边红杏倚云栽`，注云：`得此签者，必得贵婿`。”"],["黛玉把“夜深”改成“石凉”是在取笑谁？",["湘云白日醉卧石凳","宝钗","麝月"],"原文：“众人便知他趣白日间湘云醉卧的事，都笑了。”"]],"cards":[["湘云醉卧时枕着什么？","用鲛帕包的一包芍药花瓣。"],["麝月的签有什么含义？","荼蘼，“在席各饮三杯送春”，暗示花事将尽。"]],"line":["只恐夜深花睡去","深夜的会议室只剩几个人，我悄悄把灯调暗，想起一句：只恐夜深花睡去。"],"tags":["湘云","占花名","签文"]},"honglou_yousanjie":{"intro":"第六十五、六十六回写尤三姐：先是她在贾珍、贾琏面前反客为主，后是贾琏路遇柳湘莲，替她提亲。前一段是尤三姐的性情与她的自我逻辑，后一段是一个看似圆满的婚约。读时注意作者对她有两种口吻：叙事的旁观与她自己的辩白。","focus":["作者对三姐的第一眼是“松松挽着头发，大红袄子半掩半开，露着葱绿抹胸，一痕雪脯”，“柳眉笼翠雾，檀口点丹砂”，风流绰约，使二人“已酥麻如醉”。随后她“放出手眼来略试了一试”，让贾珍、贾琏“连口中一句响亮话都没了”，反客为主，“竟真是他嫖了男人，并非男人淫了他”。","她对母姊的解释是自己的原则：“咱们金玉一般的人，白叫这两个现世宝沾污了去，也算无能。”并预防凤姐的发难：“趁如今我不拿他们取乐作践准折，到那时白落个臭名，后悔不及。”她的“淫情浪态”既是反击，也是自保：不让对方轻易得手，也不愿默默被玩弄。","第二段写贾琏路遇薛蟠与柳湘莲，听说湘莲要“寻亲”，便提出“我正有一门好亲事堪配二弟”，却“只不说尤三姐自择之语”。湘莲回答“我本有愿，定要一个绝色的女子”，随即“顾不得许多了，任凭裁夺”。婚事被一问一答地敲定，却埋着“不说的部分”，这是之后悲剧的根源。"],"notes":[["绰约风流","姿态柔美"],["饧涩","眼神迷离"],["诓骗","哄骗"],["现世宝","骂人话，指丢人现眼的人"],["作践","糟蹋"],["准折","抵偿，这里指被玩弄"],["平安州","地名"],["驮子","驮运货物的牲口"],["结拜","结为异姓兄弟"],["内娣","妻妹"],["忘情","不自觉"],["昆仲","兄弟"],["高谊","深厚情义"],["撵","赶走"]],"think":["尤三姐在作者笔下既被写成“淫情浪态”，又在最后以刚烈见称。你怎样看这种矛盾？","这是作者故意设计的“不可简单归类”。前面她以放浪保护自己，也让两个男人难堪；后面她把真心留给柳湘莲，因而被疑才有刚烈。两种面貌都源于同一个动机：不愿被轻贱。读者可以不赞成她的方式，但应当看到她的处境。"],"quiz":[["尤三姐对母姊解释自己行为时说了什么？",["别白白让两个现世宝沾污了，不如我先拿他们取乐","她想嫁给贾琏","她要报复凤姐"],"原文：“咱们金玉一般的人，白叫这两个现世宝沾污了去，也算无能……趁如今我不拿他们取乐作践准折，到那时白落个臭名。”"],["贾琏向柳湘莲提亲时刻意隐瞒了什么？",["尤三姐自择的话","女方的年龄","女方的家境"],"原文：“只不说尤三姐自择之语”。"]],"cards":[["柳湘莲与薛蟠是怎样结识的？","湘莲赶走强盗救了薛蟠，两人结拜为生死弟兄。"],["贾琏要为谁与柳湘莲说亲？","他的小姨子尤三姐。"]],"line":["咱们金玉一般的人，白叫这两个现世宝沾污了去，也算无能","被人当玩物看待的人，要有自己的底线：咱们金玉一般的人，白叫这两个现世宝沾污了去，也算无能。"],"tags":["尤三姐","柳湘莲","贾琏"]},"honglou_chaojian":{"intro":"第七十四回，丢了绣春囊，王夫人追查，邢夫人的陪房王善保家的趁机提议抄检大观园，随后到探春院中受挫。前一段是借机告晴雯，后一段是探春的反抗与那段“自杀自灭”的话。它是全书家败的前兆，读时看内部倾轧怎样一步步升级。","focus":["王善保家的说话有目的：“这些女孩子们一个个倒象受了封诰似的”，把对不理睬她的丫鬟的怨气转为对制度的“忧虑”，又点名晴雯“天天打扮的象个西施的样子，在人跟前能说惯道，掐尖要强”。王夫人“猛然触动往事”，想到“水蛇腰，削肩膀，眉眼又有些象你林妹妹的”，晴雯的命运由此定下。","探春的出场与前面形成反差：她“命众丫鬟秉烛开门而待”，先发制人：“我们的丫头自然都是些贼，我就是头一个窝主。”随后说“我的东西倒许你们搜阅，要想搜我的丫头，这却不能”。她把规矩讲清楚，并保护了自己院里的人。","探春最后的话是全回的主旨：“可知这样大族人家，若从外头杀来，一时是杀不死的，这是古人曾说的`百足之虫，死而不僵`，必须先从家里自杀自灭起来，才能一败涂地！”她一边说一边“不觉流下泪来”。这不是情绪话，而是对家族处境的清醒判断。"],"notes":[["陪房","随小姐陪嫁的仆人"],["勘察","查察"],["把柄","可利用的错处"],["受了封诰","像受了朝廷封号一样傲气"],["能说惯道","能说会道"],["掐尖要强","好出风头"],["水蛇腰","细而柔软的腰"],["削肩膀","溜肩"],["对了坎儿","对上了、对得上"],["趋奉","奉承"],["窝主","窝藏者"],["箱柜","箱子与柜子"],["镜奁","梳妆镜盒"],["歹毒","狠毒"],["自杀自灭","自相残杀"],["一败涂地","彻底失败"]],"think":["探春的“自杀自灭”之说，是她对家族的绝望，还是对眼前抄检的愤怒？","两者都有，但更偏于判断。她看见的是内部互相猜忌、权力倾轧，认为这比外力冲击更致命。这话也是她理家时的结论：规矩被滥用，人心就散了。这一预言在后四十回里应验，但在前八十回里已有足够的根据。"],"quiz":[["探春对抄检者的态度是？",["先让他们搜自己，不许搜丫头","拒绝一切搜查","交出所有丫头"],"原文：“我的东西倒许你们搜阅，要想搜我的丫头，这却不能。”"],["“百足之虫，死而不僵”在探春话里表示？",["大家族不会被外力轻易击倒，只能自毁","百足虫生命力强","应当学虫子"],"她说：“若从外头杀来，一时是杀不死的……必须先从家里自杀自灭起来，才能一败涂地！”"]],"cards":[["谁向王夫人提议抄检并告晴雯？","王善保家的，邢夫人的陪房。"],["探春为什么敢让凤姐搜自己的箱柜？","丫头们的东西她全收在自己这里，一针一线都清楚，所以只许搜她不许搜丫头。"]],"line":["必须先从家里自杀自灭起来，才能一败涂地","公司的坍塌往往不是被打败，而是：必须先从家里自杀自灭起来，才能一败涂地。"],"tags":["探春","抄检","家败"]},"honglou_zhongqiu":{"intro":"第七十六回，中秋夜贾母叹人少，黛玉与湘云离开喧闹，到凹晶馆联诗。选读的两段：一段是湘云劝黛玉并解释“凸碧”“凹晶”的命名，一段是“寒塘渡鹤影，冷月葬花魂”的名联以及妙玉的出现。读时看这两句诗怎样既美又不祥，妙玉的评语又怎样给出判断。","focus":["湘云对两个馆名的说明很有见地：“山之高处，就叫凸碧；山之低洼近水，就叫作凹晶。这`凸`、`凹`二字，历来用的人最少。如今直用作轩馆之名，更觉新鲜，不落窠臼。”园子的设计与赏月有关，既是景观学，也铺垫后面的诗境。","“寒塘渡鹤影，冷月葬花魂”是全回核心。湘云先出“寒塘渡鹤影”，黛玉赞“何等自然，何等现成，何等有景且又新鲜，我竟要搁笔了”，再对以“冷月葬花魂”。湘云评“诗固新奇，只是太颓丧了些”，黛玉答“不如此如何压倒你”。意象对仗工整，却把“葬花”的悲凉推到极点。","妙玉出场点评：“好诗，好诗，果然太悲凉了。不必再往下联，若底下只这样去，反不显这两句了，倒觉得堆砌牵强。”她既是知音，又是批评者，同时说“此亦关人之气数而有”，暗示诗与命运相关。随后到栊翠庵吃茶，紫鹃翠缕来找，场面又落回日常。"],"notes":[["对景感怀","面对景物触动情怀"],["俯栏","靠着栏杆"],["窠臼","旧套路"],["凸碧","山上之馆"],["凹晶","山下近水之馆"],["颓丧","颓败沮丧"],["清奇诡谲","奇特诡异"],["搁笔","停笔"],["堆砌牵强","词语拼凑而勉强"],["气数","命运"],["龛焰","佛龛里的灯火"],["蒲团","打坐的垫子"],["不落窠臼","不落俗套"],["诗兴","作诗的兴致"]],"think":["妙玉说“此亦关人之气数而有”，你觉得诗句与命运之间真有联系吗？作者想表达什么？","从文学角度看，诗是人心情的流露，悲凉的诗反映悲凉的境况，也会加强悲凉的预感。作者让妙玉说出这样的话，是借旁观者的口说破“冷月葬花魂”对黛玉的不祥。读者不必相信“气数”，但可以看到文本如何用意象制造宿命感。"],"quiz":[["“凸碧”“凹晶”这两个馆名妙在哪里？",["用字新鲜不落窠臼，且与山水高低、赏月相关","沿用古代旧名","取自诗经"],"湘云说：“这`凸-`凹-二字，历来用的人最少……更觉新鲜，不落窠臼。”"],["妙玉对“寒塘渡鹤影，冷月葬花魂”的评价是？",["好诗，但太悲凉，不必再联","平平无奇","应该继续联下去"],"原文：“好诗，好诗，果然太悲凉了。不必再往下联，若底下只这样去，反不显这两句了。”"]],"cards":[["黛玉对的下句是什么？","“冷月葬花魂”。"],["湘云为何拉黛玉到凹晶馆？","不愿在喧闹处，想近水赏月联诗。"]],"line":["诗固新奇，只是太颓丧了些","朋友发来一首很美的诗，却满纸凄凉，我只回一句：诗固新奇，只是太颓丧了些，你得先照顾好自己。"],"tags":["黛玉湘云","联诗","妙玉"]},"honglou_qingwen":{"intro":"第七十七回晴雯被逐，宝玉偷偷去探视，二人诀别；第七十八回宝玉作《芙蓉女儿诔》祭晴雯。前一段是低声的病榻诀别，后一段是骈文式的长篇祭悼。读时看晴雯“担了虚名”的不平，以及诔文如何用古雅语言写一个丫鬟。","focus":["晴雯的话分三层：先是申辩：“我虽生的比别人略好些，并没有私情密意勾引你怎样，如何一口死咬定了我是个狐狸精！我太不服。”再是后悔：“早知如此，我当日也另有个道理。”最后是托付：“既担了虚名，越性如此，也不过这样了。”三次重复“虚名”，把她被冤枉的愤怒压成一个词。","铰指甲、换袄的细节是以物托情：“将左手上两根葱管一般的指甲齐根铰下”，“将贴身穿着的一件旧红绫袄脱下”，并说“以后就如见我一般”。她又说“我将来在棺材内独自躺着，也就象还在怡红院的一样了”。一句话把她最后的愿望——还在怡红院——写到极处。","诔文开头“窃思女儿自临人世，迄今凡十有六载”，接着以四个“不足喻”铺陈：“金玉不足喻其贵”“冰雪不足喻其洁”“星日不足喻其精”“花月不足喻其色”。随后“孰料鸠鸩恶其高，鹰鸷翻遭罦罬”，用恶鸟与香草的对立写她的遭谗。“花原自怯，岂奈狂飚？柳本多愁，何禁骤雨！”则是对她病与被逐的哀叹。文体古雅，情感却极直接。"],"notes":[["虚名","不实的坏名声"],["枯柴","干枯的木柴"],["葱管","形容手指细长"],["红绫袄","红色绫缎小袄"],["撒谎","说假话"],["湮论","湮没"],["衾枕栉沐","日常起居"],["亲昵狎亵","亲近随便"],["鸠鸩","毒鸟"],["鹰鸷","凶猛的鹰"],["薋葹","恶草"],["茝兰","香草"],["狂飚","暴风"],["膏肓","病入极深处"],["诼谣","造谣"],["夭折","早死"]],"think":["宝玉的诔文用骈文写晴雯，这种“过于华丽”的文体与她的身份相差很远，你怎么看？","这是以最高的文体致敬一个被轻视的人。骈文通常用于祭奠贵人，用在丫鬟身上，是对身份等级的反驳。也有读者认为文中的悲凉兼有对黛玉命运的预兆，这一说法存疑，可作为阅读的一个角度。"],"quiz":[["晴雯在病榻上反复强调的“虚名”指什么？",["被诬为勾引宝玉的狐狸精","名声太好","不识字的名声"],"她说：“并没有私情密意勾引你怎样，如何一口死咬定了我是个狐狸精！”"],["晴雯铰下指甲、脱下旧袄交给宝玉的用意是？",["留下信物，以后如见她一般","还债","赌气"],"她说：“这个你收了，以后就如见我一般。”"]],"cards":[["晴雯希望“在棺材里”像在哪里？","像还在怡红院一样。"],["《芙蓉女儿诔》为什么用晴雯素日所喜的物品祭奠？","用冰鲛縠写字、备她喜欢的四样食物，表达亲近。"]],"line":["既担了虚名，越性如此，也不过这样了","被误会了许久后我索性不再解释：既担了虚名，越性如此，也不过这样了。"],"tags":["晴雯","芙蓉诔","宝玉"]},"honglou_ehmeng":{"intro":"第八十二回，黛玉病中做了一场噩梦：被告知要嫁回南方，贾母冷漠，众人冷笑；醒来后又咳血，紫鹃掩饰。这是后四十回中黛玉的重要一段。后四十回的作者问题存疑，读时可以只关注这一段怎样把她的恐惧写进梦里。","focus":["梦里的逻辑很具体：凤姐说“林姑爷升了湖北的粮道，娶了一位继母”，又说“托了贾雨村作媒，将你许了你继母的什么亲戚，还说是续弦”。黛玉最怕的不是死，而是被“撂在这里”后被送走、嫁与续弦。她跪下求贾母：“老太太救我！我南边是死也不去的！”这一幕把她寄人篱下的处境写成了噩梦。","梦里众人的反应是：邢夫人使眼色，“咱们走罢”，众人“都冷笑而去”；贾母“呆着脸儿笑道：这个不干我事”。人人不救她，是黛玉对周围世界最深的不信任，也是她病中清醒与敏感的另一面。这里的冷漠不是真发生，却比真发生的更有杀伤力。","醒来的描写由内转外：“喉间犹是哽咽，心上还是乱跳，枕头上已经湿透”，又听“淅淅飒飒，又象风声，又象雨声”，到“双眸炯炯”。紫鹃倒痰盒时见“痰中好些血星”，失声后立刻改口“手里一滑，几乎撂了痰盒子”，是主仆之间最默契的掩饰。"],"notes":[["粮道","掌管粮运的官"],["继母","父亲再娶的妻子"],["续弦","丧妻后再娶"],["撂在这里","丢在这里不管"],["事体","事情的体统"],["干急","着急而无法"],["放定","订婚"],["痛定思痛","悲痛平息后回想仍痛"],["扎挣","勉强支撑"],["淅淅飒飒","风雨声"],["双眸炯炯","睁着眼睡不着"],["痰盒","盛痰的小盒"],["血星","血点"],["失言","说漏了嘴"]],"think":["黛玉的噩梦里，贾母说“这个不干我事”，这反映了黛玉对贾母的怎样的信任？","它反映的是一种深层的不安：她平日依赖贾母，却也清楚贾母的疼爱有限，一旦涉及家族利益，她未必保得住自己。梦把这种不安放大成“被冷漠对待”。读者可以由此看出黛玉的敏感并非无来由。"],"quiz":[["噩梦里黛玉最害怕的是？",["被送回南方嫁给继母的亲戚做续弦","被宝玉抛弃","被贾母责骂"],"凤姐在梦中说“托了贾雨村作媒，将你许了你继母的什么亲戚，还说是续弦”，黛玉喊“我南边是死也不去的”。"],["紫鹃发现痰盒里有血后怎样应对？",["失声后立刻改口说手滑","立刻告诉贾母","叫大夫"],"原文：“手里一滑，几乎撂了痰盒子”，是为了不让黛玉知道。"]],"cards":[["黛玉梦里向谁求救？","贾母，但贾母说“这个不干我事”。"],["紫鹃在盒里看到什么？","痰中好些血星。"]],"line":["老太太救我！我南边是死也不去的","被安排到一个不想去的岗位时，我只想大喊：老太太救我！我南边是死也不去的，现实里只能先对自己说清楚底线。"],"tags":["黛玉","噩梦","后四十回存疑"]},"honglou_fengao":{"intro":"第九十七回，黛玉焚稿断情，宝玉成婚。前一段是黛玉病中烧诗稿与旧帕，后一段是宝玉揭盖头发现新人是宝钗。后四十回的作者问题存疑，但这一回在读者心里是最有分量的一回。读时看黛玉整段没有一句对白，却用动作写完了全部心事。","focus":["焚稿的动作是一环扣一环的：“我的诗本子”，“有字的”，“狠命的撕那绢子，却是只有打颤的分儿”，然后“笼上火盆”，“瞅着那火点点头儿，往上一撂”。紫鹃“早已知他是恨宝玉”，却不敢说破，所有人物都在沉默里完成这个动作，沉默比语言更重。","她烧的是两样东西：题诗旧帕与诗稿。旧帕是宝玉送给她的，诗稿是她这些年的心事，烧掉的是“情”与“才”两样最私密的东西。“那纸沾火就着，如何能够少待，早已烘烘的着了”，几乎是一句话的瞬间，结果却是“烧得所余无几了”，写出了不可逆转。","宝玉一段是喜剧式的错位：他“妹妹身上好了？……盖着这劳什子做什么”，一揭盖头，“好象宝钗，心里不信，自己一手持灯，一手擦眼”。袭人“握了自己的嘴，笑的说不出话来”，更显得他的“傻气”。“老爷作主娶的是宝姑娘，怎么混说起林姑娘来”，是对他的当头一句，与前一段的黛玉形成正反两面。"],"notes":[["诗本子","黛玉誊抄的诗集"],["绢子","手帕"],["题诗","在帕上写的诗"],["扎挣","勉强支撑"],["回手","转手"],["烘烘","火势旺"],["傻气","痴傻之气"],["盖头","新娘盖头"],["喜娘","婚礼上扶新娘的女人"],["劳什子","讨厌的东西"],["造次","鲁莽"],["艳服","华丽的衣服"],["呆","发愣"],["糊涂","不明白"]],"think":["黛玉焚稿时没有说一句话，这种“无言”的写法有什么好处？","无言使动作成为唯一的语言，避免把她的怨与恨说破而削弱力量。同时它也让读者去想：她为什么不留？留给谁？这些问题比直接的台词更有余味。同样，宝玉揭盖头时的颠三倒四，也是用动作代替了解释。"],"quiz":[["黛玉焚烧的两样东西是？",["题诗旧帕与诗稿","书信与荷包","药方与账本"],"原文：先拿“有字的”绢子撕不动，随后“往上一撂”烧了，再把诗稿“撂在火上”。"],["宝玉揭盖头后的第一反应是？",["觉得好象宝钗，心里不信","立刻哭了","大声质问"],"原文：“宝玉睁眼一看，好象宝钗，心里不信，自己一手持灯，一手擦眼。”"]],"cards":[["黛玉烧稿时最后一个动作是什么？","身子往后一仰，几乎压倒紫鹃。"],["袭人告诉宝玉新人是谁？","宝姑娘，“老爷作主娶的”。"]],"line":["老爷作主娶的是宝姑娘，怎么混说起林姑娘来","会议里有人坚持用旧方案，我只好说：老爷作主娶的是宝姑娘，怎么混说起林姑娘来，局面已经变了。"],"tags":["黛玉焚稿","宝玉成婚","后四十回存疑"]},"honglou_guilihen":{"intro":"第九十八回，黛玉临终，紫鹃、李纨、探春相伴，恰好是宝玉成亲的时辰。前一段写黛玉最后的话，后一段写她去世后的冷清与凤姐的难处。后四十回的作者问题存疑，但这里的写法对照鲜明，值得细读：同一时辰，一边是喜乐，一边是气绝。","focus":["黛玉的遗言很简短：“我是不中用的人了”，“我的身子是干净的，你好歹叫他们送我回去”。后一句最令人动容，她至死想的是“干净”二字，与《葬花吟》里的“质本洁来还洁去”前后呼应。她不说恨，只要求回到自己来的地方。","最后一句“宝玉，宝玉，你好……”刚到“好”字便“浑身冷汗，不作声了”。句子没说完，是后世读者想象最多的地方：是“你好狠心”，还是“你好自为之”，作者都没写。这种“话断在半空”的处理，比说完更有力。","对照写在第二段：“当时黛玉气绝，正是宝玉娶宝钗的这个时辰”，“只听得远远一阵音乐之声，侧耳一听，却又没有了”，“惟有竹梢风动，月影移墙，好不凄凉冷淡”。音乐是新房那边的喜乐，竹梢风与月影是潇湘馆的冷清。凤姐的话“这件事好累坠”，点出的是贾府怕老太太搁不住的现实。"],"notes":[["回光反照","将死前短暂的清醒"],["桂圆汤","用桂圆煎的汤"],["梨汁","梨榨的汁"],["攥","握紧"],["促疾","急促"],["气绝","断气"],["停放","暂放遗体"],["凶信","不幸的消息"],["累坠","麻烦"],["见机行事","看时机行动"],["凄凉冷淡","冷清悲凉"],["潇湘馆","黛玉居所"]],"think":["黛玉最后一句“宝玉，宝玉，你好……”停在“好”字，为什么这种断句最能打动读者？","因为读者会替她补上最想听的话。不同的读者补出的不同，使这句话成为一个开放的情感出口。作者没有给明确答案，是在让情感直接传给读者。这也是文学里“省略”的力量。"],"quiz":[["黛玉的遗愿是什么？",["她的身子是干净的，希望被送回去","与宝玉合葬","让紫鹃陪着她"],"原文：“我的身子是干净的，你好歹叫他们送我回去。”"],["作者用“远远一阵音乐之声”写什么？",["新房那边的喜乐，与潇湘馆的死形成对照","有人在唱戏","黛玉的幻觉"],"同一时辰：黛玉气绝，宝玉成亲，音乐是喜乐之声，传到潇湘馆又消失。"]],"cards":[["黛玉临终最后一句话是什么？","“宝玉，宝玉，你好……”"],["黛玉去世时正是什么时辰？","宝玉娶宝钗的时辰。"]],"line":["我的身子是干净的，你好歹叫他们送我回去","走到人生的某个关口，我只想对自己说：我的身子是干净的，你好歹叫他们送我回去，别让我失去来处。"],"tags":["黛玉之死","后四十回存疑","对照"]},"honglou_chachao":{"intro":"第一零五回，锦衣府带人到荣国府宣旨查抄，贾政正在设宴。前一段是赵堂官笑着进门的“来头不好”，后一段是抄查的开始与西平王的拿捏。后四十回的作者问题存疑，但抄家一幕与前八十回里的“树倒猢狲散”相呼应，读时可以对照第十三回秦可卿的托梦。","focus":["来者先笑：“赵堂官满脸笑容，并不说什么”，“只拉着贾政的手，笑着说了几句寒温的话”。众人“看见来头不好，也有躲进里间屋里的，也有垂手侍立的”。作者用“笑”和“不说”来写危险，比喊打喊杀更让人心里发凉。","西平王的出场是另一种分寸：“笑嘻嘻的说道：无事不敢轻造，有奉旨交办事件，要赦老接旨。”他先让“亲友各散”，再留“本宅的人听候”。官场上的上下手分工清楚：堂官手紧，王爷手松，贾政等人只能“连忙跪接”。","抄查开始后，赵堂官抢着说“传齐司员，带同番役，分头按房抄查登帐”，西平王则要“按房封锁”，“且请内眷回避”，两个人立场不同，一个要“尽行查抄”，一个要“慢慢的”。“查出御用衣裙并多少禁用之物”“重利盘剥”这些罪名，也与前面的奢华与放债形成因果。"],"notes":[["堂官","衙门主官"],["司官","衙门中层官员"],["番役","差役"],["登帐","登记造册"],["罗唣","吵闹滋扰"],["封门","封锁门户"],["抄查","搜查财物"],["回避","避开"],["禁用之物","违禁物品"],["重利盘剥","高利放贷"],["面面相看","互相看看不知所措"],["摩拳擦掌","形容迫不及待"]],"think":["作者写抄家为什么先写“笑”，而不是直接写“抄”？这对读者有什么影响？","因为笑把危险包在客气里，让人物和读者都在惊愕中失去判断。直接写抄，只能写结果；先写笑，才能写出“从日常滑入危机”的过程。这个手法在小说里常用，能更真实地写出权力的运作。"],"quiz":[["赵堂官一进门的态度是？",["满脸笑容，并不说什么","怒气冲冲","低声下气"],"原文：“赵堂官满脸笑容，并不说什么，一径走上厅来。”"],["西平王对在场亲友的安排是？",["请亲友散去，留下本宅的人听候","让他们一起接旨","先抄亲友"],"原文：“且请众位府上亲友各散，独留本宅的人听候。”"]],"cards":[["抄家时众人的反应有哪几种？","躲进里间屋的，垂手侍立的，面面相看的。"],["西平王对内眷有什么吩咐？","先传信后宅，请内眷回避，再查不迟。"]],"line":["无事不敢轻造，有奉旨交办事件","领导突然登门，我心里一沉：无事不敢轻造，有奉旨交办事件，今天怕是没好消息。"],"tags":["抄家","赵堂官","家败"]},"honglou_yuanyangxun":{"intro":"第一一一回，贾母去世，鸳鸯在辞灵后失踪，最后在老太太套间里自缢。前一段是鸳鸯的内心与秦可卿幻影，后一段是她死后众人的反应。后四十回的作者问题存疑，但这一回与第四十六回鸳鸯抗婚首尾相接，值得对照阅读。","focus":["鸳鸯的决定不是只为主人去世，而是对未来的判断：“大老爷虽不在家，大太太的这样行为我也瞧不上。老爷是不管事的人，以后便乱世为王起来了，我们这些人不是要叫他们掇弄了么。”她算得清楚，“我是受不得这样折磨的，倒不如死了干净”，与抗婚时的刚烈同一个脾气。","秦氏幻影是整段的叙事转折：鸳鸯进门“只见灯光惨淡，隐隐有个女人拿着汗巾子好似要上吊的样子”，认出是“东府里的小蓉大奶奶”，并认为是来教她“死的法儿”。这个情节把前面十三回的秦可卿与此处串起来，有强烈的宿命色彩，读者不必当真，但要注意作者的用意。","她死后的处理有三重声音：贾政“他是殉葬的人，不可作丫头论”，让宝玉磕头；邢夫人说“不要折受他不得超生”，拒绝贾琏行礼；宝钗奠酒，“眼泪早扑簌簌流下来了”。三个人的态度不一样，说明一个丫鬟的死怎样被不同人解释。"],"notes":[["辞灵","出殡前向灵位告别"],["哭奠","哭着祭奠"],["撺掇","怂恿"],["掇弄","摆布"],["乱世为王","没人管时各自为政"],["折磨","折腾"],["汗巾","腰带"],["绞的一绺头发","当年铰下的那绺头发"],["殉葬","陪葬"],["折受","受不起"],["超生","转世"],["奠酒","把酒洒地祭奠"]],"think":["鸳鸯自缢是殉主，还是对未来的逃避？作者怎样处理这种“两难”？","两者兼有。她的话里有对贾母的恩情，也有“受不得这样折磨”的自保；作者用贾政的“殉葬之人”给了她一个体面，却没有把她的真正动机说破。这样的处理让读者看到：一个人的死，既是个人决定，也是制度压力的结果。"],"quiz":[["鸳鸯决定去死的主要考虑是？",["对贾母去世后境遇的判断，宁死也不受折磨","被责骂","与宝玉赌气"],"她想到“大太太的这样行为我也瞧不上……我是受不得这样折磨的，倒不如死了干净”。"],["贾政怎样评价鸳鸯的死？",["他是殉葬的人，不可作丫头论","她太糊涂","她不该这样做"],"原文：“他是殉葬的人，不可作丫头论。你们小一辈都该行个礼。”"]],"cards":[["鸳鸯在套间看见谁的幻影？","东府已死的秦可卿，拿着汗巾像要上吊。"],["鸳鸯带在怀里的是什么？","当年绞下的一绺头发。"]],"line":["他是殉葬的人，不可作丫头论","对一位在岗位上过世的老员工，我们会说：他是殉葬的人，不可作丫头论，要以敬意相待。"],"tags":["鸳鸯","殉主","后四十回存疑"]},"honglou_fengtuo":{"intro":"第一一三回，凤姐病重，刘姥姥来探，凤姐把巧姐托给她。前一段写巧姐请安、刘姥姥说“做媒”的玩笑，后一段写刘姥姥回忆受过的恩惠。后四十回的作者问题存疑，但这一回与第六回刘姥姥一进荣国府首尾呼应，从“打秋风”到“救后人”，是一个很完整的弧。","focus":["凤姐对巧姐说：“你的名字还是他起的呢，就和干娘一样，你给他请个安。”一句话把前面“刘姥姥为她取名”的因缘接上。刘姥姥“不要折杀我了！”把乡下人的谦卑写得充分，又笑着说“我给姑娘做个媒罢”，带着玩笑，却暗合后文巧姐的归宿。","凤姐的态度出人意料：刘姥姥说“庄家人”，她回答“你说去，我愿意就给”。这是病中人对未来的托付，而不是玩笑。刘姥姥说“就是姑奶奶肯了，上头太太们也不给”，说得很现实。巧姐觉得“这话不好听”，走去和青儿玩，两个小女孩“渐渐的就熟起来了”，是一个很自然的伏笔。","平儿把刘姥姥拉开，凤姐却又留她：“忙什么，你坐下，我问你近来的日子还过的么？”刘姥姥“千恩万谢”，说“我们若不仗着姑奶奶”，回应的是第六回的二十两银子之恩。这一幕说明恩情不是一次性的，而是在时间里一点点沉淀。"],"notes":[["干娘","认的母亲"],["折杀","受不起而减福"],["蝈蝈儿","一种鸣虫"],["屯乡","乡村"],["庄家人","农村人"],["千金贵体","尊贵之身"],["绫罗","华贵的丝织品"],["坑杀","害死"],["做个媒","说亲"],["搅烦","打扰"],["嚼吃","吃的用度"],["顽话","玩笑话"],["请个安","问好行礼"],["青儿","刘姥姥的外孙女"]],"think":["凤姐为什么愿意把巧姐托给刘姥姥？这背后有什么逻辑？","因为她看出这个人情最干净：刘姥姥无所求，只记恩情。贾府里的亲戚多半有利益牵连，唯独她是真心感念。凤姐一生用权术，临终却选择了最朴素的信任，这种反转也是作者对“恩情”的评价。"],"quiz":[["刘姥姥对凤姐说的“做媒”的话，凤姐的回答是？",["你说去，我愿意就给","不行，太太们不答应","这是玩笑"],"原文：“凤姐道：你说去，我愿意就给。”"],["刘姥姥谦称巧姐是“千金贵体”，意在表达什么？",["农村日子艰苦，她养不起","她想要钱","她看不起巧姐"],"原文：“姑娘这样千金贵体，绫罗裹大了的，吃的是好东西，到了我们那里，我拿什么哄他顽”。"]],"cards":[["巧姐的名字是谁起的？","刘姥姥。"],["刘姥姥为什么说“就是姑奶奶肯了，上头太太们也不给”？","她明白巧姐的婚事不是凤姐一人能定，也体谅身份差距。"]],"line":["你的名字还是他起的呢，就和干娘一样，你给他请个安","带新人给多年的老客户打招呼，我会说：你的名字还是他起的呢，就和干娘一样，你给他请个安。"],"tags":["凤姐","刘姥姥","巧姐"]},"honglou_ciqin":{"intro":"第一一九回宝玉与贾兰赴考前辞别王夫人、李纨，第一二零回在雪中向贾政拜别。前一段是辞行，后一段是出家。后四十回的作者问题存疑，但这两段的写法克制，几乎不加评论。读时看宝玉在辞别时如何每一句都有两层意思。","focus":["辞别王夫人时，宝玉“跪着不肯起来”，说“母亲生我一世，我也无可答报，只有这一入场用心作了文章，好好的中个举人出来”，既是安慰，也是告别。“一辈子的不好也都遮过去了”，王夫人听了“更觉伤心起来”，是因为她隐约感到不祥。","他对老太太说：“只不过隔了形质，并非隔了神气啊。”这是宝玉最像“出世者”的一句话。李纨“觉得光景不大吉祥”，连忙打断。他又对李纨作揖，说“日后兰哥还有大出息，大嫂子还要带凤冠穿霞帔呢”，字字是祝愿，字字是告别。","雪中拜别一幕几乎无话：贾政见“光着头，赤着脚，身上披着一领大红猩猩毡的斗篷，向贾政倒身下拜”，“拜了四拜”，“打了个问讯”。一僧一道说“俗缘已毕，还不快走”，三人“飘然登岸而去”，歌曰“我所居兮，青埂之峰”，结束于“白茫茫一片旷野”。这里的“白茫茫”呼应第五回“白茫茫大地真干净”。"],"notes":[["下场","参加科举考试"],["孤孤凄凄","孤单凄凉"],["形质","形体质地"],["神气","精神气质"],["凤冠穿霞帔","富贵妇人的礼服"],["不大吉祥","不太吉利"],["猩猩毡","红色呢料"],["倒身下拜","向前拜倒"],["问讯","僧人合掌致礼"],["俗缘已毕","尘世的缘分已完"],["青埂","青埂峰"],["鸿蒙太空","混沌宇宙"],["旷野","空旷的野外"],["渺渺茫茫","遥远模糊"]],"think":["宝玉在辞别时说的话都像祝愿，却暗含告别，作者为什么不让他说破？","因为说破就变成了解释，而作者想要的是“让人事后才懂”的效果。每个人听到的是自己能懂的那一层，王夫人听到的是孝，李纨听到的是祝福，只有读者看出告别。这是一种克制的悲剧写法。"],"quiz":[["宝玉对王夫人说“一辈子的不好也都遮过去了”，王夫人为什么更伤心？",["她感到这像告别，不祥","他承诺不再顽皮","他承认过失"],"文中：“王夫人听了，更觉伤心起来。”李纨“觉得光景不大吉祥”。"],["雪中一僧一道对宝玉说的话是？",["俗缘已毕，还不快走","你跟我们走吧","你还有未了之事"],"原文：“一僧一道，夹住宝玉说道：俗缘已毕，还不快走。”"]],"cards":[["宝玉在雪中穿的是什么？","大红猩猩毡斗篷，光头赤脚。"],["他们歌中说的住处是哪里？","青埂之峰，鸿蒙太空。"]],"line":["只不过隔了形质，并非隔了神气啊","想念已故的亲人时，我对自己说：只不过隔了形质，并非隔了神气啊。"],"tags":["宝玉出家","雪中拜别","后四十回存疑"]},"honglou_jiehe":{"intro":"第一二零回，贾雨村被革职后遇甄士隐，在急流津觉迷渡受点化；空空道人把《石头记》抄给曹雪芹，雪芹笑着说“果然是贾雨村言”，空空道人大笑而去。后四十回的作者问题存疑，但这一回的收束与第一回首尾相接，读时看“荒唐”“假语村言”怎样被重新定义。","focus":["士隐对雨村说“一念之间，尘凡顿易”，并解释宝玉的下落：“此玉早已离世。一为避祸，二为撮合，从此夙缘一了，形质归一。”“太虚幻境即是真如福地。一番阅册，原始要终之道，历历生平，如何不悟？”这些话把全书的神话框架做了一次回顾与解说。","士隐对“情”的断语是：“凡是情思缠绵的，那结果就不可问了。”他说“淫”字固不可犯，“只这`情`字也是沾染不得的”。这句话既是对元春以下诸人结局的总括，也与第五回“情天孽海”呼应。读者可以不同意，但要看到这是全书为“情”下的最后一个定义。","空空道人将《石头记》交给雪芹，雪芹说“既是假语村言，但无鲁鱼亥豕以及背谬矛盾之处，乐得与二三同志，酒余饭饱，雨夕灯窗之下，同消寂寞”，把写作说成一种“消遣”。空空道人听后“仰天大笑”，说“果然是敷衍荒唐！不但作者不知，抄者不知，并阅者也不知”，与第一回的“满纸荒唐言”首尾相应。"],"notes":[["仙长","对修道者的尊称"],["一念之间","一个念头之间"],["夙缘","前世的缘分"],["太虚幻境","第五回的仙境"],["真如福地","佛教的清净之境"],["情天孽海","情的天地、孽的海"],["口孽","因言语造的孽"],["舛错","错误"],["鲁鱼亥豕","传抄中的字形错误"],["刻舟求剑","拘泥不通"],["胶柱鼓瑟","死板不知变通"],["敷衍荒唐","信口编造"],["陶情适性","陶冶情性"],["悼红轩","曹雪芹书房名"]],"think":["第一二零回的收束把全书说成“假语村言”和“敷衍荒唐”，这是在消解小说，还是在加强它？","在加强。作者用“荒唐”把读者从“考证真假”的追问里引开，让注意力回到“滋味”本身。空空道人说“不但作者不知，抄者不知，并阅者也不知”，是在承认意义无法被固定，所以读者才是真正的续写者。"],"quiz":[["士隐对“情”字的断语是？",["情思缠绵的，结果就不可问","情是人生最大的福分","情与淫不同，所以无忧"],"原文：“那`淫`字固不可犯，只这`情`字也是沾染不得的……凡是情思缠绵的，那结果就不可问了。”"],["曹雪芹对空空道人说“假语村言”，意思是？",["写作只是借假话村话，不必追问真假","书中全是真事","书是雨村写的"],"原文：“既是假语村言，但无鲁鱼亥豕以及背谬矛盾之处，乐得与二三同志……同消寂寞。”"]],"cards":[["全书最后空空道人说的话是？","“果然是敷衍荒唐！不但作者不知，抄者不知，并阅者也不知。”"],["甄士隐与贾雨村在哪里再次相见？","急流津觉迷渡。"]],"line":["果然是敷衍荒唐！不但作者不知，抄者不知，并阅者也不知","读完一份冗长的报告，我只想笑着对自己说：果然是敷衍荒唐！不但作者不知，抄者不知，并阅者也不知。"],"tags":["全书结尾","空空道人","后四十回存疑"]}});
